///////////////////////////////////////////////\n// CATÁLOGO CENTRAL\n//////////////////////////////////////////////////////\n\n/// Produto global do grupo, identificado por CNP.\nmodel Produto {\n  id                        String              @id @default(cuid())\n  cnp                       Int                 @unique\n  /// Identificador do produto no ERP da farmácia (Softreis: Stocks.CodigoID).\n  /// Mantido como referência cross-tenant — útil para o agent fazer\n  /// lookup rápido sem JOIN, MAS não é chave canónica: o ERP pode\n  /// reciclar CodigoIDs e produtos diferentes em farmácias diferentes\n  /// do mesmo tenant podem partilhar valores (são namespaces locais).\n  /// Identidade real do catálogo vive em `cnp @unique`. Index\n  /// não-unique para preservar perf de lookups.\n  externalProductId         Int?\n  designacao                String\n  fabricanteId              String?\n  classificacaoNivel1Id     String?\n  classificacaoNivel2Id     String?\n  tipoArtigo                String?\n  codigoATC                 String?\n  dci                       String?\n  imagemUrl                 String?\n  formaFarmaceutica         String?\n  dosagem                   String?\n  embalagem                 String?\n  flagGenerico              Boolean             @default(false)\n  flagMSRM                  Boolean             @default(false)\n  flagMNSRM                 Boolean             @default(false)\n  /// MNSRM **não comparticipado** (Softreis: Stocks.MNSRM_NCompart). Distinto\n  /// de `flagMNSRM` (OTC); este sinaliza OTC que não tem comparticipação SNS.\n  flagMnsrmNCompart         Boolean             @default(false)\n  grupoHomogeneo            String?\n  estado                    ProdutoEstado       @default(PENDENTE)\n  origemDados               ProdutoOrigemDados  @default(FARMACIA)\n  validadoManualmente       Boolean             @default(false)\n  // Classificação e verificação automática\n  productType               String?\n  productTypeConfidence     Float?\n  classificationSource      String?\n  classificationVersion     String?\n  /// Autoridade da classificação N1/N2. Ver `ClassificacaoEstado`.\n  classificacaoEstado       ClassificacaoEstado @default(AUSENTE)\n  /// Proveniência legível: REGRA | MODELO | MODELO_PROVISORIO |\n  /// MODELO_PROPAGADO | ERP | GLOBAL | MANUAL | PRE_PROVENIENCIA.\n  ///\n  /// Texto e não enum: é campo de auditoria, e um valor novo não deve\n  /// custar uma migração. O que a aplicação DECIDE está no enum acima.\n  classificacaoOrigem       String?\n  classificacaoConfianca    Float?\n  /// Versão do processo que escreveu — \"ke-2.1\" para as provisórias.\n  classificacaoVersao       String?\n  verificationStatus        VerificationStatus  @default(PENDING)\n  lastVerifiedAt            DateTime?\n  lastVerificationAttemptAt DateTime?\n  externallyVerified        Boolean             @default(false)\n  needsManualReview         Boolean             @default(false)\n  manualReviewReason        String?\n  dataCriacao               DateTime            @default(now())\n  dataAtualizacao           DateTime            @updatedAt\n\n  fabricante          Fabricante?    @relation(fields: [fabricanteId], references: [id])\n  classificacaoNivel1 Classificacao? @relation(\"ProdutoClassificacaoNivel1\", fields: [classificacaoNivel1Id], references: [id])\n  classificacaoNivel2 Classificacao? @relation(\"ProdutoClassificacaoNivel2\", fields: [classificacaoNivel2Id], references: [id])\n\n  produtosFarmacia      ProdutoFarmacia[]\n  vendas                Venda[]\n  vendasMensais         VendaMensal[]\n  compras               Compra[]\n  devolucoes            Devolucao[]\n  historicoStocks       HistoricoStock[]\n  ajustesStock          AjusteStock[]\n  linhasInventario      LinhaInventario[]\n  indicadores           IndicadoresProdutoFarmacia[]\n  linhasEncomenda       LinhaEncomenda[]\n  filaRevisao           FilaRevisao[]\n  filaEnriquecimento    EnriquecimentoFila[]\n  verificacaoHistorico  ProdutoVerificacaoHistorico[]\n  utilizacoes           ProdutoUtilizacao[]\n  enrichmentSourceLogs  EnrichmentSourceLog[]\n  ingestVendasLinhasRaw IngestVendaLinhaRaw[]\n  movimentos            MovimentoArtigo[]\n\n  @@index([fabricanteId])\n  @@index([classificacaoNivel1Id])\n  @@index([classificacaoNivel2Id])\n  @@index([estado])\n  @@index([verificationStatus])\n  @@index([classificacaoEstado])\n  @@index([productType])\n  @@index([lastVerifiedAt])\n  @@index([externalProductId])\n}\n\n/// Fabricante normalizado.\nmodel Fabricante {\n  id              String         @id @default(cuid())\n  nomeNormalizado String         @unique\n  paisOrigem      String?\n  estado          EntidadeEstado @default(ATIVO)\n  dataCriacao     DateTime       @default(now())\n  dataAtualizacao DateTime       @updatedAt\n\n  aliases  FabricanteAlias[]\n  produtos Produto[]\n}\n\n/// Variantes de nomes de fabricante encontradas nas origens.\nmodel FabricanteAlias {\n  id           String @id @default(cuid())\n  fabricanteId String\n  aliasNome    String\n\n  fabricante Fabricante @relation(fields: [fabricanteId], references: [id], onDelete: Cascade)\n\n  @@unique([fabricanteId, aliasNome])\n  @@index([aliasNome])\n}\n\n/// Árvore de classificação central.\nmodel Classificacao {\n  id                 String            @id @default(cuid())\n  nome               String\n  tipo               TipoClassificacao\n  classificacaoPaiId String?\n  estado             EntidadeEstado    @default(ATIVO)\n  ordem              Int?\n  dataCriacao        DateTime          @default(now())\n  dataAtualizacao    DateTime          @updatedAt\n\n  classificacaoPai  Classificacao?  @relation(\"ClassificacaoPaiFilho\", fields: [classificacaoPaiId], references: [id])\n  subClassificacoes Classificacao[] @relation(\"ClassificacaoPaiFilho\")\n\n  produtosNivel1 Produto[] @relation(\"ProdutoClassificacaoNivel1\")\n  produtosNivel2 Produto[] @relation(\"ProdutoClassificacaoNivel2\")\n\n  @@unique([nome, tipo, classificacaoPaiId])\n  @@index([tipo])\n  @@index([classificacaoPaiId])\n}\n\n/// Utilização/necessidade — vocabulário CONTROLADO, para pesquisa\n/// operacional ao balcão (\"produtos para tosse\", \"dor\", \"alergias\").\n///\n/// Não é taxonomia. A árvore `Classificacao` responde a \"o que é este\n/// produto?\" e cada produto tem exactamente um lugar nela. Isto responde\n/// a \"para que serve?\", e um produto tem tantas respostas quantas as\n/// necessidades que cobre — um xarope pode servir tosse seca e irritação\n/// da garganta sem deixar de ser um só artigo num só ramo da árvore.\n/// Misturar as duas coisas obrigaria a duplicar produtos na taxonomia ou\n/// a inventar subcategorias por sintoma, que é o que se quer evitar.\n///\n/// Vocabulário fechado: as linhas vêm de `lib/catalog/utilizacoes.ts` e\n/// entram por seed. Não há caminho de escrita que crie utilizações a\n/// partir de texto do utilizador — sem isso, \"tosse\", \"Tosse\" e \"p/\n/// tosse\" viravam três facetas em três meses.\n///\n/// O `slug` é a chave partilhada entre tenants: cada tenant tem a sua\n/// base, mas `tosse` significa o mesmo em todas, e um relatório de grupo\n/// pode agregar sem tradução.\nmodel Utilizacao {\n  id String @id @default(cuid())\n\n  /// Estável e igual em todos os tenants. Nunca renomear — mudar um slug\n  /// desliga as associações que já existem noutras bases.\n  slug      String   @unique\n  nome      String\n  /// Onde acaba esta utilização e começa a seguinte. Serve para quem\n  /// classifica decidir sem inventar critério.\n  descricao String?\n  /// Termos que o operador escreve mas não são o nome canónico\n  /// (\"expectorante\" -> tosse-produtiva). Alimentam a pesquisa.\n  sinonimos String[] @default([])\n\n  /// Agrupador só para apresentação (ex.: \"Respiratório\"). Não é um nível\n  /// de hierarquia: nada se pendura por baixo de uma utilização.\n  grupo String?\n\n  estado          EntidadeEstado @default(ATIVO)\n  ordem           Int?\n  dataCriacao     DateTime       @default(now())\n  dataAtualizacao DateTime       @updatedAt\n\n  produtos ProdutoUtilizacao[]\n\n  @@index([estado])\n  @@index([grupo])\n}\n\n/// Produto <-> Utilização. N:N puro, com proveniência.\n///\n/// A proveniência não é decoração: sem ela, uma associação inferida por\n/// regra e uma validada por um farmacêutico ficam indistinguíveis, e a\n/// próxima passagem automática sobrescreve a segunda com a primeira.\nmodel ProdutoUtilizacao {\n  produtoId    String\n  utilizacaoId String\n\n  /// Quem associou: \"REGRA\", \"MANUAL\", \"ERP\", nome do classificador.\n  fonte       String\n  /// 0–1. NULL quando a origem é manual — uma decisão humana não tem\n  /// probabilidade associada.\n  confianca   Float?\n  dataCriacao DateTime @default(now())\n\n  produto    Produto    @relation(fields: [produtoId], references: [id], onDelete: Cascade)\n  utilizacao Utilizacao @relation(fields: [utilizacaoId], references: [id], onDelete: Cascade)\n\n  @@id([produtoId, utilizacaoId])\n  @@index([utilizacaoId])\n  @@index([fonte])\n}\n\n/// Fronteira temporal de uma corrida de `products-upload`, medida pelo\n/// relógio do SERVIDOR.\n///\n/// Existe por uma razão só: o sweep que marca produtos como retirados não\n/// pode depender do relógio da máquina da farmácia. O agent enviava um\n/// `runStartedAt` gerado em Windows, sem NTP garantido; se esse relógio\n/// estivesse adiantado, todas as linhas escritas durante a corrida\n/// ficavam com `dataAtualizacao` anterior ao corte e o sweep retirava o\n/// catálogo inteiro que acabara de ser carregado — com `ok: true`.\n///\n/// A corrida é aberta pelo próprio servidor no primeiro batch de\n/// produtos daquela farmácia, e é `startedAtServer` que serve de corte.\n/// O `runStartedAt` do agent continua a viajar no protocolo, mas só como\n/// telemetria: nunca entra num WHERE que altere dados.\n///\n/// Não substitui `PipelineRun` (audit log por farmácia, escrito pelo\n/// agent): isto é estado de uma corrida em curso, com um único registo\n/// aberto por farmácia de cada vez.\nmodel IngestProdutoRun {\n  id         String @id @default(cuid())\n  farmaciaId String\n\n  /// O corte. Instante do relógio da base, no primeiro batch da corrida.\n  startedAtServer   DateTime @default(now())\n  /// Actualizado a cada batch. Serve para detectar corridas abandonadas.\n  lastBatchAtServer DateTime @default(now())\n  /// Quantos produtos esta corrida entregou. Alimenta a defesa contra\n  /// sweeps anormais: uma corrida que entregou 100 linhas não pode\n  /// retirar 18 000.\n  produtosRecebidos Int      @default(0)\n\n  /// ABERTA | FINALIZADA | ABANDONADA\n  estado       String    @default(\"ABERTA\")\n  finalizadaEm DateTime?\n  /// Quantas linhas o sweep marcou. Null enquanto não finalizou.\n  retiradas    Int?\n\n  farmacia Farmacia @relation(fields: [farmaciaId], references: [id], onDelete: Cascade)\n\n  /// Uma corrida ABERTA por farmácia — garantido pela base e não pela\n  /// aplicação, senão dois batches concorrentes criavam duas e o sweep\n  /// passava a ter dois cortes possíveis.\n  ///\n  /// É um índice único PARCIAL (`WHERE estado = 'ABERTA'`), criado na\n  /// migração: o Prisma não exprime unicidade condicional, e um\n  /// @@unique([farmaciaId, estado]) proibiria duas corridas FINALIZADA\n  /// na mesma farmácia, que é precisamente o caso normal.\n  @@index([farmaciaId, estado])\n  @@index([farmaciaId, startedAtServer])\n}\n\n/// Um documento de compra do ERP, com o veredicto sobre se as suas\n/// linhas explicam o valor financeiro.\n///\n/// Derivada de `StagingCompraRawLine`, recalculada a cada agregação.\n/// Existe porque a classificação NÃO cabe em `Compra`: essa é agregada\n/// por (produto, dia, fornecedor) e pode juntar vários documentos, logo\n/// um total documental posto numa linha de `Compra` seria rateio com\n/// outro nome — e ratear o total pelas linhas sobreviventes atribuiria\n/// a produtos conhecidos o custo de produtos que desapareceram do ERP.\n///\n/// A investigação (agent rev56) provou que em documentos como o 58865 as\n/// linhas em falta não existem em tabela nenhuma: o ERP conserva quanto\n/// se pagou e já não conserva por quê.\nmodel CompraDocumento {\n  id         String @id @default(cuid())\n  farmaciaId String\n\n  /// `Recepcao.[Recepcao ID]`. Identidade do documento no ERP.\n  externalReceptionId     Int\n  externalTipoDocumentoId Int?\n  externalFornecedorId    Int\n  externalNRecepcao       Int?\n  dataRecepcao            DateTime\n\n  /// `Recepcao.[Total Incidencia_EUR]` — o que o documento vale.\n  totalDocumentoEur Decimal @db.Decimal(14, 2)\n  /// Σ(quantidade × valorEurUnit) das linhas que ainda existem.\n  valorExplicadoEur Decimal @db.Decimal(14, 2)\n  /// valorExplicado − totalDocumento. Positivo: linhas somam mais.\n  deltaEur          Decimal @db.Decimal(14, 2)\n  nLinhas           Int\n\n  /// RECONCILIADA | DETALHE_INCOMPLETO | NAO_FINANCEIRO | SEM_LINHAS.\n  /// Texto e não enum: acrescentar uma classe não deve exigir migração\n  /// enquanto o domínio ainda está a ser aprendido.\n  qualidade String\n\n  /// Batch da agregação que produziu esta linha.\n  ingestBatchId String?\n  calculadoEm   DateTime @default(now())\n\n  farmacia Farmacia @relation(fields: [farmaciaId], references: [id], onDelete: Cascade)\n\n  @@unique([farmaciaId, externalReceptionId])\n  @@index([farmaciaId, qualidade])\n  @@index([farmaciaId, dataRecepcao])\n  @@index([farmaciaId, externalTipoDocumentoId])\n}\n\n/// Uma linha por execução de um backfill de catálogo.\n///\n/// Existe para responder a \"estamos a melhorar?\" — uma cobertura de 21%\n/// não diz nada isolada; 18% → 21% → 37% diz tudo. Sem isto, cada corrida\n/// imprime números no terminal e perde-os, e a única forma de comparar é\n/// procurar mensagens antigas.\n///\n/// Não usa PipelineRun: esse é por farmácia e exige `farmaciaId`, e um\n/// backfill de catálogo corre sobre o catálogo inteiro do tenant.\nmodel CatalogoBackfillRun {\n  id String @id @default(cuid())\n\n  /// Que backfill correu — \"utilizacoes\", \"classificacao\", …\n  kind        String\n  executadoEm DateTime @default(now())\n\n  produtosAnalisados    Int\n  produtosClassificados Int\n  associacoes           Int\n  /// Candidatas que as regras produziram mas ficaram abaixo do limiar.\n  /// Contar isto é o que distingue \"não há sinal\" de \"há sinal fraco\".\n  recusadas             Int\n\n  /// Redundante face aos dois primeiros, mas guardado à mesma: um dia a\n  /// definição de \"analisado\" muda e a série histórica tem de continuar\n  /// a ser lida como foi calculada na altura.\n  coberturaPercent Float\n\n  /// Limiar em vigor nessa corrida. Sem ele, uma subida de cobertura pode\n  /// ser trabalho novo ou apenas o limiar ter descido.\n  limiarConfianca Float?\n  /// Commit ou revisão das regras, quando conhecido.\n  versaoRegras    String?\n\n  /// Detalhe livre: TOP utilizações, recusadas por regra, cobertura por tipo.\n  detalhes Json @default(\"{}\")\n\n  @@index([kind, executadoEm])\n}\n\n/// Snapshot local do catálogo INFARMED de medicamentos (Portugal).\n///\n/// Origem: ficheiro descarregado do portal INFARMED (INFOMED / Open Data).\n/// Importado por scripts/import-infarmed-snapshot.ts, idempotente por CNP.\n///\n/// Consultado pelo infarmedConnector em lib/catalog-connectors.ts,\n/// que devolve tier=REGULATORY e confidence=0.95 quando há match por CNP.\n/// É a primeira fonte autoritária para escrever Produto.fabricanteId / dci / codigoATC.\nmodel InfarmedSnapshot {\n  id                String   @id @default(cuid())\n  cnp               Int      @unique\n  designacaoOficial String\n  dci               String?\n  codigoATC         String?\n  /// Titular da Autorização de Introdução no Mercado — fabricante canónico.\n  titularAim        String?\n  formaFarmaceutica String?\n  dosagem           String?\n  embalagem         String?\n  grupoTerapeutico  String?\n  /// Estado regulamentar: \"Autorizado\", \"Suspenso\", \"Revogado\", \"Caducado\".\n  /// Produtos não-\"Autorizado\" não são devolvidos pelo conector.\n  estadoAim         String?\n  /// Identificador do ficheiro/data do snapshot (ex: \"2026-04\"). Permite\n  /// detectar quando uma reimportação trouxe dados mais recentes.\n  snapshotVersion   String\n  importedAt        DateTime @default(now())\n\n  @@index([snapshotVersion])\n  @@index([estadoAim])\n}\n\n/// Camada regulatória v2 (Maio 2026). Tabela standalone, indexada por CNP,\n/// alimentada pelo importador genérico `scripts/import-regulatory-record.ts`\n/// a partir de qualquer fonte (CEDIME/ANF, INFARMED Open Data, listas\n/// comparticipados, genéricos, etc.).\n///\n/// MVP simples — sem provenance per-field, sem versioning multi-source,\n/// sem conflict engine. Merge por CNP com regra \"preservar não-null\":\n/// um import só sobrescreve campos já preenchidos quando corrido com `--force`.\n///\n/// O `infarmedConnector` em `lib/catalog-connectors.ts` lê esta tabela\n/// primeiro e cai em `InfarmedSnapshot` quando o CNP não está aqui.\nmodel RegulatoryRecord {\n  cnp               Int      @id\n  designacaoOficial String?\n  dci               String?\n  codigoATC         String?\n  formaFarmaceutica String?\n  dosagem           String?\n  embalagem         String?\n  grupoTerapeutico  String?\n  /// Titular da AIM (fabricante regulatório).\n  titularAim        String?\n  /// \"Autorizado\", \"Suspenso\", \"Revogado\", \"Caducado\", etc.\n  estadoAim         String?\n  /// Tag livre identificando a fonte/import (ex.: \"cedime_anf_2026-05\",\n  /// \"infarmed_comparticipados_2026-04\"). O último import vence em campos\n  /// que sobrescreva.\n  source            String\n  importedAt        DateTime @default(now())\n  updatedAt         DateTime @updatedAt\n\n  @@index([codigoATC])\n  @@index([dci])\n  @@index([source])\n  @@index([estadoAim])\n}\n\n/// Job da regulatory acquisition pipeline (Phase 0 — Maio 2026).\n///\n/// Cada produto que precisa de fetch regulatório (DCI, ATC, forma, dosagem,\n/// embalagem, titularAim) entra como um job nesta queue. Workers stateless\n/// processam jobs em background, tentam fontes externas em ordem de\n/// prioridade, e populam `RegulatoryRecord` quando obtêm dados.\n///\n/// Lifecycle (ver enum AcquisitionJobStatus):\n///   PENDING → IN_PROGRESS → { DONE, PARTIAL, FAILED, BLOCKED }\n///\n/// Worker — `scripts/workers/regulatory-acquisition-worker.ts`:\n///   · Claim com FOR UPDATE SKIP LOCKED (safe para múltiplos workers)\n///   · Backoff exponencial (1h, 4h, 1d, 3d, 7d) até MAX_ATTEMPTS=6\n///   · GC: jobs IN_PROGRESS há > 30min são reset a PENDING (worker crashed)\n///\n/// Enqueue — `scripts/enqueue-regulatory-acquisition.ts`:\n///   · Por CNP / lista de CNPs / cohort predefinido / ficheiro\n///   · Upsert com priority configurável\n///\n/// Phase 0 (esta versão): zero fetchers reais. Worker simula outcome\n/// determinístico para validar o lifecycle. Phase 1+ adiciona fetchers\n/// (INFARMED Infomed, WHO ATC, manufacturer pages, etc.).\nmodel RegulatoryAcquisitionJob {\n  id              String               @id @default(cuid())\n  cnp             Int                  @unique\n  designacao      String?\n  status          AcquisitionJobStatus @default(PENDING)\n  /// Prioridade — menor = primeiro. 1=urgente, 50=normal (default), 100=fundo.\n  priority        Int                  @default(50)\n  attempts        Int                  @default(0)\n  /// Última fonte tentada (para diagnóstico): \"infarmed_infomed\", \"manufacturer_page\", …\n  lastSourceTried String?\n  lastError       String?\n  lastAttemptAt   DateTime?\n  /// Backoff scheduling — jobs só são claimable quando NOW() >= nextAttemptAt.\n  nextAttemptAt   DateTime             @default(now())\n  /// Lista de campos já populados em RegulatoryRecord para este CNP\n  /// (snapshot na altura do último processamento). Usada para evitar\n  /// retentar campos já obtidos.\n  fieldsObtained  String[]             @default([])\n  /// Resumo bruto de cada fonte tentada (debug). Exemplo:\n  /// { \"infarmed_infomed\": { ok: true, fields: [\"dci\",\"atc\"] },\n  ///   \"manufacturer_page\": { ok: false, reason: \"no match\" } }\n  sourceResults   Json?\n  /// Quando atinge status DONE pela primeira vez. Não é actualizado em\n  /// re-runs subsequentes.\n  completedAt     DateTime?\n  createdAt       DateTime             @default(now())\n  updatedAt       DateTime             @updatedAt\n\n  @@index([status, nextAttemptAt])\n  @@index([priority, nextAttemptAt])\n}\n\n/// Histórico de verificações automáticas por produto.\nmodel ProdutoVerificacaoHistorico {\n  id                 String   @id @default(cuid())\n  produtoId          String\n  verificadoEm       DateTime @default(now())\n  productType        String?\n  productTypeConf    Float?\n  verificationStatus String\n  sourceSummary      Json?\n  fieldsUpdated      String[]\n\n  produto Produto @relation(fields: [produtoId], references: [id], onDelete: Cascade)\n\n  @@index([produtoId, verificadoEm])\n}\n\n/// Resultado de cada chamada a um conector externo.\n///\n/// Granularidade: uma row por (produto × conector × tentativa) — alimenta\n/// as métricas de qualidade de fonte em /admin/catalogo E a evidência\n/// detalhada em /admin/catalogo/revisao/[id].\n///\n/// Status:\n///   SUCCESS     — match forte; dados extraídos com confiança suficiente.\n///   PARTIAL_HIT — página/registo encontrado mas com dados incompletos\n///                 ou similaridade média. Útil mostrar ao admin.\n///   NO_MATCH    — sem candidato. Conector tentou mas não achou nada.\n///   ERROR       — exceção (timeout, HTTP, parse). errorMessage truncada\n///                 a 500 chars.\n///\n/// Append-only. Não há UPDATE; reverify gera nova row.\nmodel EnrichmentSourceLog {\n  id             String                 @id @default(cuid())\n  produtoId      String\n  source         String\n  status         EnrichmentSourceStatus\n  /// Confiança devolvida pela fonte para este produto. Preenchido em SUCCESS e PARTIAL_HIT.\n  confidence     Float?\n  /// \"cnp\" | \"sku\" | \"designacao\" | \"fuzzy_name\" | \"ean\" | \"unknown\".\n  matchedBy      String?\n  durationMs     Int?\n  /// Lista de campos não-null devolvidos pela fonte (fabricante, atc, categoria, …).\n  /// Permite contar coverage por campo por fonte.\n  fieldsReturned String[]\n  errorMessage   String?\n  /// URL da página/registo de onde os dados vieram, quando aplicável.\n  /// Crucial para conectores web (retail_pharmacy) — admin pode abrir a página.\n  url            String?\n  /// Query exacta enviada à fonte (DDG, OFF/OBF, etc.). Permite reproduzir a busca.\n  query          String?\n  /// Marca / fabricante exactamente como aparece na fonte, antes de qualquer\n  /// normalização. Mostrado ao admin como sinal cru.\n  rawBrand       String?\n  /// Categoria/breadcrumb cru, antes do mapeamento canónico.\n  rawCategory    String?\n  /// Nome do produto na fonte (og:title, h1, designacaoOficial, etc.).\n  /// Permite ao admin ver se o conector apanhou o produto certo.\n  rawProductName String?\n  createdAt      DateTime               @default(now())\n\n  produto Produto @relation(fields: [produtoId], references: [id], onDelete: Cascade)\n\n  @@index([source, createdAt])\n  @@index([produtoId, createdAt])\n  @@index([status, createdAt])\n}\n\nenum EnrichmentSourceStatus {\n  SUCCESS\n  NO_MATCH\n  ERROR\n  PARTIAL_HIT\n}\n\n/// Fornecedor normalizado.\n///\n/// `nomeNormalizado` é canónico GLOBAL no tenant (uma row por fornecedor real).\n/// Várias farmácias do mesmo tenant partilham a mesma row de Fornecedor via\n/// `FornecedorErpRef` — cada farmácia tem o seu próprio `Fornecedor ID` interno\n/// no SPharm local, mas mapeiam para o mesmo Fornecedor canónico SaaS.\n///\n/// Campos `nome` e `nif` são metadados derivados do ERP (Fornecedores.[Nome\n/// Fornecedor] e [Numero Contribuinte]), populados pelo bootstrap de\n/// fornecedores. Nullable porque pré-existem rows de Fornecedor criadas por\n/// outros fluxos (encomendas, vendas históricas) sem este detalhe.\nmodel Fornecedor {\n  id              String         @id @default(cuid())\n  nomeNormalizado String         @unique\n  /// Nome completo do fornecedor (ex: \"MEPHA - INV. DESEN. FAB. F LDA\"),\n  /// derivado de dbo.Fornecedores.[Nome Fornecedor]. Pode ser igual a\n  /// `nomeNormalizado` quando o ERP só tem nome abreviado.\n  nome            String?\n  /// NIF / Número Contribuinte. Pode ficar NULL — no SPharm Cotovia ~50%\n  /// dos fornecedores não têm NIF preenchido. Não usar como chave natural.\n  nif             String?\n  tipo            FornecedorTipo @default(OUTRO)\n  estado          EntidadeEstado @default(ATIVO)\n  dataCriacao     DateTime       @default(now())\n  dataAtualizacao DateTime       @updatedAt\n\n  aliases                     FornecedorAlias[]\n  erpRefs                     FornecedorErpRef[]\n  produtosFarmacia            ProdutoFarmacia[]\n  compras                     Compra[]                     @relation(\"CompraFornecedor\")\n  devolucoesDestino           Devolucao[]                  @relation(\"DevolucaoFornecedorDestino\")\n  indicadoresUltimoFornecedor IndicadoresProdutoFarmacia[] @relation(\"IndicadorUltimoFornecedor\")\n  linhasEncomenda             LinhaEncomenda[]             @relation(\"LinhaEncomendaFornecedorSugerido\")\n}\n\n/// Variantes de nomes de fornecedor.\nmodel FornecedorAlias {\n  id           String @id @default(cuid())\n  fornecedorId String\n  aliasNome    String\n\n  fornecedor Fornecedor @relation(fields: [fornecedorId], references: [id], onDelete: Cascade)\n\n  @@unique([fornecedorId, aliasNome])\n  @@index([aliasNome])\n}\n\n/// Link per-farmácia ↔ Fornecedor canónico, com snapshot dos metadados do\n/// ERP local no momento da última sync. Permite idempotência\n/// `(farmaciaId, externalFornecedorId)` mantendo o `Fornecedor` canónico\n/// partilhável entre farmácias do mesmo tenant.\n///\n/// Source: dbo.Fornecedores (Softreis) + LEFT JOIN a Tbl_Tipo_Fornecedores\n/// para denormalizar a descrição do tipo.\nmodel FornecedorErpRef {\n  id                    String   @id @default(cuid())\n  fornecedorId          String\n  farmaciaId            String\n  /// Valor de dbo.Fornecedores.[Fornecedor ID] no SPharm local desta farmácia.\n  externalFornecedorId  Int\n  /// Snapshot dos campos do ERP (auditoria + re-derivação).\n  nomeAbreviadoErp      String\n  nomeFornecedorErp     String?\n  nifErp                String?\n  tipoFornecedorErpId   Int?\n  tipoFornecedorErpDesc String?\n  inactivoErp           Boolean  @default(false)\n  /// Última vez que esta ref foi tocada pelo agent (UPSERT).\n  lastSyncedAt          DateTime @default(now()) @updatedAt\n  /// Batch ULID emitido pelo agent na sync. Útil para reconciliação de\n  /// \"que linhas vieram nesta passagem?\".\n  ingestBatchId         String?\n\n  fornecedor Fornecedor @relation(fields: [fornecedorId], references: [id], onDelete: Cascade)\n  farmacia   Farmacia   @relation(fields: [farmaciaId], references: [id], onDelete: Cascade)\n\n  @@unique([farmaciaId, externalFornecedorId])\n  @@index([fornecedorId])\n  @@index([farmaciaId, inactivoErp])\n  @@index([farmaciaId, lastSyncedAt])\n}\n\n//////////////////////////////////////////////////////\n// ESTRUTURA MULTI-FARMÁCIA\n//////////////////////////////////////////////////////\n\nmodel Farmacia {\n  id              String         @id @default(cuid())\n  nome            String\n  codigoANF       String?\n  morada          String?\n  contacto        String?\n  estado          EntidadeEstado @default(ATIVO)\n  dataAdesao      DateTime       @default(now())\n  dataCriacao     DateTime       @default(now())\n  dataAtualizacao DateTime       @updatedAt\n\n  utilizadores                        Utilizador[]\n  utilizadoresExtra                   UtilizadorFarmacia[]\n  produtosFarmacia                    ProdutoFarmacia[]\n  produtosInternos                    ProdutoInterno[]\n  vendas                              Venda[]\n  vendasMensais                       VendaMensal[]\n  compras                             Compra[]\n  devolucoes                          Devolucao[]\n  historicoStocks                     HistoricoStock[]\n  ajustesStock                        AjusteStock[]\n  inventarios                         Inventario[]\n  indicadores                         IndicadoresProdutoFarmacia[]\n  listasEncomenda                     ListaEncomenda[]\n  lotesIngestao                       LoteIngestao[]\n  emailConfig                         EmailConfig?\n  ingestVendasLinhasRaw               IngestVendaLinhaRaw[]\n  pipelineRuns                        PipelineRun[]\n  fornecedorErpRefs                   FornecedorErpRef[]\n  stagingComprasRawLines              StagingCompraRawLine[]\n  stagingDevolucoesFornecedorRawLines StagingDevolucaoFornecedorRawLine[]\n  movimentos                          MovimentoArtigo[]\n  ingestProdutoRuns                   IngestProdutoRun[]\n  compraDocumentos                    CompraDocumento[]\n  ingestStocksMovRaw                  IngestStocksMovRaw[]\n\n  /// OBSOLETA desde 2026-08-18 — já NÃO escolhe fonte nenhuma.\n  ///\n  /// Era a flag que decidia se o extrato lia `MovimentoArtigo` ou o\n  /// \"modelo legacy\" (Venda/Compra/Devolucao). Esse ramo saiu: a tabela\n  /// `Venda` nunca é escrita por código nenhum, portanto o legacy era\n  /// incapaz de mostrar uma venda — e com a flag a `false` em produção\n  /// era exactamente isso que acontecia. Ver o cabeçalho de\n  /// `lib/movimentos-data.ts`.\n  ///\n  /// A coluna fica por remover numa migração própria, para que este\n  /// commit não misture correcção de comportamento com alteração de\n  /// schema. `scripts/admin/backfill-movimentos-tenant.ts` ainda a\n  /// escreve; deixou de ter efeito na UI.\n  useMovimentosCanonical Boolean @default(false)\n\n  @@unique([nome])\n  @@index([codigoANF])\n}\n\n// Configuração SMTP por farmácia. Quando farmaciaId é null, é a\n// configuração global usada como fallback. A password é guardada\n// cifrada (AES-256-GCM) — ver lib/email-crypto.ts.\nmodel EmailConfig {\n  id                String    @id @default(cuid())\n  farmaciaId        String?   @unique\n  farmacia          Farmacia? @relation(fields: [farmaciaId], references: [id], onDelete: Cascade)\n  smtpHost          String\n  smtpPort          Int\n  smtpUser          String?\n  smtpPassEncrypted String?\n  smtpSecure        Boolean   @default(false)\n  fromEmail         String\n  fromName          String?\n  replyTo           String?\n  isActive          Boolean   @default(true)\n  lastTestAt        DateTime?\n  lastTestStatus    String?\n  lastTestError     String?\n  dataCriacao       DateTime  @default(now())\n  dataAtualizacao   DateTime  @updatedAt\n}\n\nmodel Utilizador {\n  id                 String           @id @default(cuid())\n  email              String           @unique\n  nome               String\n  perfil             UtilizadorPerfil\n  /// Farmácia PRIMÁRIA (contexto por defeito para sessão e filtros).\n  /// Para GESTOR_GRUPO/ADMINISTRADOR é opcional. Para acesso a várias\n  /// farmácias usar a relação `farmacias` (UtilizadorFarmacia).\n  farmaciaId         String?\n  estado             EntidadeEstado   @default(ATIVO)\n  passwordHash       String?\n  /// Marca o próximo login como forçado a alterar a password (ex:\n  /// reset administrativo). A API /login vai validar e redirigir.\n  mustChangePassword Boolean          @default(false)\n  ultimoLogin        DateTime?\n  dataCriacao        DateTime         @default(now())\n  dataAtualizacao    DateTime         @updatedAt\n\n  farmacia        Farmacia?            @relation(fields: [farmaciaId], references: [id])\n  farmacias       UtilizadorFarmacia[]\n  listasEncomenda ListaEncomenda[]\n  auditoria       AuditLog[]           @relation(\"AuditLogActor\")\n}\n\n/// Associação N:N utilizador → farmácias para perfis com acesso a\n/// múltiplas (ex: GESTOR_GRUPO, GESTOR_FARMACIA com mais do que uma).\n/// Pode ser ignorado quando `Utilizador.perfil = ADMINISTRADOR`, que\n/// por contrato tem acesso a TODAS as farmácias.\nmodel UtilizadorFarmacia {\n  id           String   @id @default(cuid())\n  utilizadorId String\n  farmaciaId   String\n  dataCriacao  DateTime @default(now())\n\n  utilizador Utilizador @relation(fields: [utilizadorId], references: [id], onDelete: Cascade)\n  farmacia   Farmacia   @relation(fields: [farmaciaId], references: [id], onDelete: Cascade)\n\n  @@unique([utilizadorId, farmaciaId])\n  @@index([farmaciaId])\n}\n\n/// Auditoria básica — regista acções relevantes do utilizador.\n/// Fica propositadamente genérico (string action + JSON meta) para\n/// não acoplar a um domínio específico. Chamar `logAudit(...)` do\n/// server-side quando uma acção precisa ser rastreável.\nmodel AuditLog {\n  id        String   @id @default(cuid())\n  actorId   String?\n  action    String\n  entity    String?\n  entityId  String?\n  metaJson  String?\n  ip        String?\n  userAgent String?\n  createdAt DateTime @default(now())\n\n  actor Utilizador? @relation(\"AuditLogActor\", fields: [actorId], references: [id])\n\n  @@index([actorId, createdAt])\n  @@index([entity, entityId])\n  @@index([action, createdAt])\n}\n\n//////////////////////////////////////////////////////\n// PRODUTO POR FARMÁCIA\n//////////////////////////////////////////////////////\n\n/// Tudo o que varia entre farmácias vive aqui.\nmodel ProdutoFarmacia {\n  id                   String    @id @default(cuid())\n  produtoId            String\n  farmaciaId           String\n  /// Denormalizado do `Produto.externalProductId` para lookups rápidos\n  /// do agent sem join (ex: stock-upload precisa de mapear CodigoID →\n  /// produtoId em batch). Atualizado pelo endpoint /bootstrap/products.\n  externalProductId    Int?\n  designacaoLocal      String?\n  pvp                  Decimal?  @db.Decimal(12, 4)\n  pmc                  Decimal?  @db.Decimal(12, 4)\n  puc                  Decimal?  @db.Decimal(12, 4)\n  stockAtual           Decimal?  @db.Decimal(14, 3)\n  stockRaw             Decimal?  @db.Decimal(14, 3)\n  stockMinimo          Decimal?  @db.Decimal(14, 3)\n  stockMaximo          Decimal?  @db.Decimal(14, 3)\n  /// Stock em encomenda (Softreis: ArmazensStocks.[Existencia Encomenda]).\n  /// Soma per-produto across armazéns na ingestão bootstrap.\n  stockEncomenda       Decimal?  @db.Decimal(14, 3)\n  /// Stock reservado (Softreis: ArmazensStocks.[Existencia Reserva]).\n  stockReserva         Decimal?  @db.Decimal(14, 3)\n  fornecedorHabitualId String?\n  /// ID do fornecedor habitual no ERP da farmácia (Softreis:\n  /// ArmazensStocks.[Fornecedor Habitual]). Raw, sem resolução para\n  /// Fornecedor.id — utilizado apenas para audit/debug do bootstrap.\n  fornecedorExternalId Int?\n  dataUltimaVenda      DateTime?\n  dataUltimaCompra     DateTime?\n  validadeMaisAntiga   DateTime?\n  flagRetirado         Boolean   @default(false)\n  modeloGestaoStock    String?\n  familiaOrigem        String?\n  categoriaOrigem      String?\n  subcategoriaOrigem   String?\n  /// Fornecedor/distribuidor habitual da farmácia (NÃO é o fabricante real\n  /// do produto — é o grossista que vende o produto à farmácia: Empifarma,\n  /// OCP, Alliance, etc.). Usado apenas como contexto interno, análise de\n  /// abastecimento e hints fracos. NUNCA como fabricante canónico.\n  fornecedorOrigem     String?\n\n  // ── IVA (rev39 + recuperador) ───────────────────────────────────\n  /// Taxa IVA canónica de farmácia em pontos percentuais inteiros:\n  /// 6, 13, 23 ou NULL. Resultado de pipeline de recuperação que\n  /// combina (em cascata, ver `lib/iva-recovery.ts`):\n  ///   1. STOCKS_MESTRE        — `dbo.Stocks.[IVA]` via agent rev39+\n  ///   2. STAGING_COMPRA       — última `StagingCompraRawLine.iva`\n  ///   3. STAGING_DEVOLUCAO    — última `StagingDevolucaoFornecedor*.iva`\n  ///   4. VENDA_DERIVADA       — moda da taxa derivada por linha de venda\n  /// Valores fora de {6,13,23} ou ausentes → permanece NULL (\"IVA por\n  /// apurar\"). Nunca inventamos.\n  taxaIvaPercent   Int?\n  /// Fonte que populou `taxaIvaPercent`. Token uppercase: ver enum\n  /// `TaxaIvaSource` em lib/iva-recovery. NULL ⇒ taxaIvaPercent é NULL.\n  taxaIvaSource    String?\n  /// Timestamp da última execução do recuperador que tocou nesta linha.\n  /// Distinto de `dataAtualizacao` para permitir auditoria do pipeline\n  /// sem ruído de outros campos.\n  taxaIvaUpdatedAt DateTime?\n\n  dataAtualizacao DateTime @updatedAt\n  dataCriacao     DateTime @default(now())\n\n  produto            Produto     @relation(fields: [produtoId], references: [id], onDelete: Cascade)\n  farmacia           Farmacia    @relation(fields: [farmaciaId], references: [id], onDelete: Cascade)\n  fornecedorHabitual Fornecedor? @relation(fields: [fornecedorHabitualId], references: [id])\n\n  @@unique([produtoId, farmaciaId])\n  @@index([farmaciaId])\n  @@index([produtoId])\n  @@index([farmaciaId, externalProductId])\n  @@index([fornecedorHabitualId])\n  @@index([flagRetirado])\n  // Suporta filtragem rápida em buckets \"Por taxa IVA\" no relatório\n  // Inventário (4 buckets canónicos: 6/13/23/null).\n  @@index([taxaIvaPercent])\n}\n\n//////////////////////////////////////////////////////\n// PRODUTOS INTERNOS\n//////////////////////////////////////////////////////\n\n/// Produtos internos/localizados apenas na farmácia.\nmodel ProdutoInterno {\n  id              String   @id @default(cuid())\n  farmaciaId      String\n  codigoInterno   Int\n  designacao      String?\n  tipoArtigo      String?\n  pvp             Decimal? @db.Decimal(12, 4)\n  puc             Decimal? @db.Decimal(12, 4)\n  stockAtual      Decimal? @db.Decimal(14, 3)\n  flagRetirado    Boolean  @default(false)\n  dataCriacao     DateTime @default(now())\n  dataAtualizacao DateTime @updatedAt\n  loteIngestaoId  String?\n\n  farmacia     Farmacia      @relation(fields: [farmaciaId], references: [id], onDelete: Cascade)\n  loteIngestao LoteIngestao? @relation(fields: [loteIngestaoId], references: [id])\n\n  ajustesStock     AjusteStock[]\n  linhasInventario LinhaInventario[]\n\n  @@unique([farmaciaId, codigoInterno])\n  @@index([farmaciaId])\n  @@index([codigoInterno])\n}\n\n//////////////////////////////////////////////////////\n// DADOS TRANSACIONAIS\n//////////////////////////////////////////////////////\n\n/// Vendas diárias agregadas por produto-dia-farmácia.\nmodel Venda {\n  id                   String     @id @default(cuid())\n  farmaciaId           String\n  produtoId            String\n  data                 DateTime\n  quantidade           Decimal    @db.Decimal(14, 3)\n  valorTotal           Decimal    @db.Decimal(14, 2)\n  valorUnitario        Decimal?   @db.Decimal(12, 4)\n  custoUnitario        Decimal?   @db.Decimal(12, 4)\n  tipoVenda            TipoVenda?\n  valorComparticipacao Decimal?   @db.Decimal(14, 2)\n  valorPagoUtente      Decimal?   @db.Decimal(14, 2)\n  numeroTransacoes     Int?\n  dataIngestao         DateTime   @default(now())\n  loteIngestaoId       String?\n\n  farmacia     Farmacia      @relation(fields: [farmaciaId], references: [id], onDelete: Cascade)\n  produto      Produto       @relation(fields: [produtoId], references: [id], onDelete: Cascade)\n  loteIngestao LoteIngestao? @relation(fields: [loteIngestaoId], references: [id])\n\n  @@index([farmaciaId, data])\n  @@index([produtoId, data])\n  @@index([farmaciaId, produtoId, data])\n  @@index([loteIngestaoId])\n}\n\n/// Vendas mensais agregadas. Granularidade canónica:\n/// `(farmaciaId, produtoId, ano, mes)`.\n///\n/// Fontes possíveis (campo `origemAgregacao`):\n///   · \"agent-bootstrap-staging\"  — agregação server-side de\n///     IngestVendaLinhaRaw via `scripts/aggregate-vendamensal.ts`\n///   · null / legado              — import Excel ou outras fontes\n///     pré-aggregation script (legacy)\n///\n/// Campos legados (`quantidade`, `valorTotal`, `mesCompleto`,\n/// `origemBootstrap`, `dataAtualizacao`, `loteIngestaoId`)\n/// preservados para compatibilidade com loaders e dashboards\n/// existentes — `aggregate-vendamensal.ts` populá-os a partir dos\n/// novos campos para que o dashboard continue intacto.\nmodel VendaMensal {\n  id         String @id @default(cuid())\n  farmaciaId String\n  produtoId  String\n  ano        Int\n  mes        Int\n\n  // ── Campos legados (NOT NULL, populados por loaders Excel + agg script)\n  quantidade      Decimal  @db.Decimal(14, 3)\n  valorTotal      Decimal  @db.Decimal(14, 2)\n  mesCompleto     Boolean  @default(true)\n  origemBootstrap Boolean  @default(false)\n  dataAtualizacao DateTime @updatedAt\n  loteIngestaoId  String?\n\n  // ── Campos da agregação (nullable até script popular) ──────────────\n  /// SUM assinado de quantidade (VENDA=+, DEVOLUCAO_ANULACAO=−).\n  quantidadeLiquida   Decimal? @db.Decimal(14, 3)\n  /// SUM assinado de pvpUnitario × quantidade. \"Bruto\" = teto comercial.\n  valorBruto          Decimal? @db.Decimal(14, 2)\n  /// SUM assinado de valorLinha (semântica observada: pago utente).\n  valorPagoUtente     Decimal? @db.Decimal(14, 2)\n  /// SUM assinado de comparticipacao1 + comparticipacao2.\n  valorComparticipado Decimal? @db.Decimal(14, 2)\n  /// COUNT(*) de linhas que compuseram a agregação.\n  linhasVenda         Int?\n  /// COUNT(DISTINCT externalSaleId) — número de atendimentos distintos.\n  atendimentos        Int?\n  /// Marcador da origem da agregação. Permite distinguir rows\n  /// agregadas server-side de rows legadas Excel-import.\n  origemAgregacao     String?\n  /// Timestamp da primeira escrita do row (separa criação de actualização).\n  createdAt           DateTime @default(now())\n\n  /// A natureza da venda: \"NORMAL\" | \"CREDITO\" | \"TRANSFERENCIA\".\n  ///\n  /// FAZ PARTE DA CHAVE. Sem isto, ligar e desligar as vendas a crédito\n  /// no mapa obrigava a reprocessar o histórico — e o relatório oficial\n  /// do SPharm alterna esses interruptores à vontade.\n  ///\n  /// As linhas que já existiam são todas NORMAL, e isso não é uma\n  /// suposição: os readers de crédito e transferência ainda não existem,\n  /// portanto nada do que está gravado pode ter outra natureza. O default\n  /// preserva o histórico inteiro sem reprocessamento.\n  naturezaVenda String @default(\"NORMAL\")\n\n  farmacia     Farmacia      @relation(fields: [farmaciaId], references: [id], onDelete: Cascade)\n  produto      Produto       @relation(fields: [produtoId], references: [id], onDelete: Cascade)\n  loteIngestao LoteIngestao? @relation(fields: [loteIngestaoId], references: [id])\n\n  @@unique([farmaciaId, produtoId, ano, mes, naturezaVenda])\n  @@index([ano, mes])\n  @@index([farmaciaId, ano, mes])\n  @@index([produtoId, ano, mes])\n  @@index([origemAgregacao])\n  @@index([farmaciaId, ano, mes, naturezaVenda])\n}\n\n/// Compras diárias agregadas por produto-dia-farmácia-fornecedor.\n///\n/// Granularidade: 1 row por (farmaciaId, produtoId, fornecedorId, data).\n/// A aggregation Phase 1c soma todas as linhas de `StagingCompraRawLine`\n/// resolvidas (produto + fornecedor) que caem no mesmo dia e produz/UPSERTa\n/// esta row. O unique `Compra_aggregation_key` garante idempotência da\n/// re-aggregation — re-correr a mesma janela actualiza valores em vez de\n/// duplicar.\n///\n/// Campos `ingestBatchId` e `aggregatedAt` ficam `null` em rows legacy\n/// (excel import, etc.) — não tocadas pelo aggregation pipeline nesta fase.\nmodel Compra {\n  id                  String    @id @default(cuid())\n  farmaciaId          String\n  produtoId           String\n  fornecedorId        String?\n  data                DateTime\n  quantidade          Decimal   @db.Decimal(14, 3)\n  valorTotal          Decimal   @db.Decimal(14, 2)\n  precoUnitario       Decimal?  @db.Decimal(12, 4)\n  descontoBonificacao Decimal?  @db.Decimal(14, 2)\n  numeroDocumento     String?\n  dataIngestao        DateTime  @default(now())\n  loteIngestaoId      String?\n  /// Batch ULID emitido pela aggregation. Permite cleanup direccionado\n  /// (`DELETE WHERE ingestBatchId = ?`) e auditoria \"que run produziu esta row?\".\n  ingestBatchId       String?\n  /// Quando a row foi (re)produzida pela aggregation. NULL → row legacy\n  /// não tocada pelo pipeline 1c.\n  aggregatedAt        DateTime?\n  /// true quando TODAS as linhas que formaram esta row vieram de\n  /// documentos RECONCILIADOS. Só então `precoUnitario` representa um\n  /// custo real e pode alimentar `ultimoPrecoCompra`.\n  ///\n  /// Um booleano e não o valor do documento: `Compra` é agregada por\n  /// produto-dia e pode juntar documentos, portanto guardar aqui um\n  /// total documental convidaria ao rateio que está proibido. O valor\n  /// financeiro do documento vive em `CompraDocumento` e fica lá.\n  ///\n  /// NULL = agregação anterior a esta classificação, estado desconhecido.\n  /// Quem calcula custo trata NULL como não fiável.\n  custoFiavel         Boolean?\n\n  farmacia     Farmacia      @relation(fields: [farmaciaId], references: [id], onDelete: Cascade)\n  produto      Produto       @relation(fields: [produtoId], references: [id], onDelete: Cascade)\n  fornecedor   Fornecedor?   @relation(\"CompraFornecedor\", fields: [fornecedorId], references: [id])\n  loteIngestao LoteIngestao? @relation(fields: [loteIngestaoId], references: [id])\n\n  /// Idempotência da aggregation (granularidade produto-dia-fornecedor-farmácia).\n  /// fornecedorId é nullable → Postgres aceita múltiplos NULLs no unique.\n  /// Mitigação: aggregation nunca produz rows com fornecedorId NULL (são\n  /// orphans e ficam fora do write).\n  @@unique([farmaciaId, produtoId, fornecedorId, data], name: \"Compra_aggregation_key\")\n  @@index([farmaciaId, data])\n  @@index([produtoId, data])\n  @@index([fornecedorId])\n  @@index([farmaciaId, produtoId, data])\n  @@index([loteIngestaoId])\n  @@index([ingestBatchId])\n  @@index([aggregatedAt])\n}\n\n/// Devoluções diárias.\n///\n/// Granularidade: 1 row por linha do staging (`StagingDevolucaoFornecedorRawLine`).\n/// `externalLineId` é a chave natural (dbo.[Devolucao Detalhe].[Devolucao\n/// Detalhe ID]); idempotência da aggregation via UPSERT em\n/// `(farmaciaId, externalLineId)`. Estado P→R muda `quantidadeRecebida`\n/// no staging e a aggregation re-produz a row sem duplicar.\n///\n/// `externalLineId`/`ingestBatchId`/`aggregatedAt` ficam `null` em rows\n/// legacy (excel import, etc.).\nmodel Devolucao {\n  id                  String        @id @default(cuid())\n  farmaciaId          String\n  produtoId           String\n  /// dbo.[Devolucao Detalhe].[Devolucao Detalhe ID]. NULL em rows legacy.\n  externalLineId      Int?\n  data                DateTime\n  quantidade          Decimal       @db.Decimal(14, 3)\n  valor               Decimal       @db.Decimal(14, 2)\n  tipo                TipoDevolucao\n  motivo              String?\n  fornecedorDestinoId String?\n  dataIngestao        DateTime      @default(now())\n  loteIngestaoId      String?\n  ingestBatchId       String?\n  aggregatedAt        DateTime?\n\n  farmacia          Farmacia      @relation(fields: [farmaciaId], references: [id], onDelete: Cascade)\n  produto           Produto       @relation(fields: [produtoId], references: [id], onDelete: Cascade)\n  fornecedorDestino Fornecedor?   @relation(\"DevolucaoFornecedorDestino\", fields: [fornecedorDestinoId], references: [id])\n  loteIngestao      LoteIngestao? @relation(fields: [loteIngestaoId], references: [id])\n\n  /// Idempotência da aggregation Phase 1c (granularidade linha).\n  /// Múltiplos NULLs permitidos (rows legacy não conflitam).\n  @@unique([farmaciaId, externalLineId])\n  @@index([farmaciaId, data])\n  @@index([produtoId, data])\n  @@index([tipo])\n  @@index([fornecedorDestinoId])\n  @@index([loteIngestaoId])\n  @@index([ingestBatchId])\n  @@index([aggregatedAt])\n}\n\n/// Histórico periódico de stock por produto-farmácia.\nmodel HistoricoStock {\n  id             String   @id @default(cuid())\n  farmaciaId     String\n  produtoId      String\n  dataFotografia DateTime\n  quantidade     Decimal  @db.Decimal(14, 3)\n  valorCusto     Decimal? @db.Decimal(14, 2)\n  loteIngestaoId String?\n\n  farmacia     Farmacia      @relation(fields: [farmaciaId], references: [id], onDelete: Cascade)\n  produto      Produto       @relation(fields: [produtoId], references: [id], onDelete: Cascade)\n  loteIngestao LoteIngestao? @relation(fields: [loteIngestaoId], references: [id])\n\n  @@unique([farmaciaId, produtoId, dataFotografia])\n  @@index([farmaciaId, dataFotografia])\n  @@index([produtoId, dataFotografia])\n}\n\n//////////////////////////////////////////////////////\n// AJUSTES E INVENTÁRIO\n//////////////////////////////////////////////////////\n\n/// Ajustes manuais de stock ou correções operacionais.\nmodel AjusteStock {\n  id               String          @id @default(cuid())\n  farmaciaId       String\n  produtoId        String?\n  produtoInternoId String?\n  data             DateTime\n  tipo             TipoAjusteStock\n  quantidade       Decimal         @db.Decimal(14, 3)\n  valor            Decimal?        @db.Decimal(14, 2)\n  motivo           String?\n  observacoes      String?\n  dataIngestao     DateTime        @default(now())\n  loteIngestaoId   String?\n\n  farmacia       Farmacia        @relation(fields: [farmaciaId], references: [id], onDelete: Cascade)\n  produto        Produto?        @relation(fields: [produtoId], references: [id], onDelete: Cascade)\n  produtoInterno ProdutoInterno? @relation(fields: [produtoInternoId], references: [id], onDelete: Cascade)\n  loteIngestao   LoteIngestao?   @relation(fields: [loteIngestaoId], references: [id])\n\n  @@index([farmaciaId, data])\n  @@index([produtoId, data])\n  @@index([produtoInternoId, data])\n  @@index([tipo])\n  @@index([loteIngestaoId])\n}\n\n/// Cabeçalho de inventário físico da farmácia.\nmodel Inventario {\n  id              String           @id @default(cuid())\n  farmaciaId      String\n  nome            String?\n  dataInventario  DateTime\n  estado          EstadoInventario @default(RASCUNHO)\n  observacoes     String?\n  dataCriacao     DateTime         @default(now())\n  dataAtualizacao DateTime         @updatedAt\n  loteIngestaoId  String?\n\n  farmacia     Farmacia          @relation(fields: [farmaciaId], references: [id], onDelete: Cascade)\n  loteIngestao LoteIngestao?     @relation(fields: [loteIngestaoId], references: [id])\n  linhas       LinhaInventario[]\n\n  @@index([farmaciaId, dataInventario])\n  @@index([estado])\n}\n\n/// Linhas do inventário por produto.\nmodel LinhaInventario {\n  id               String   @id @default(cuid())\n  inventarioId     String\n  produtoId        String?\n  produtoInternoId String?\n  stockSistema     Decimal? @db.Decimal(14, 3)\n  stockContado     Decimal  @db.Decimal(14, 3)\n  diferenca        Decimal? @db.Decimal(14, 3)\n  valorDiferenca   Decimal? @db.Decimal(14, 2)\n  observacoes      String?\n\n  inventario     Inventario      @relation(fields: [inventarioId], references: [id], onDelete: Cascade)\n  produto        Produto?        @relation(fields: [produtoId], references: [id], onDelete: Cascade)\n  produtoInterno ProdutoInterno? @relation(fields: [produtoInternoId], references: [id], onDelete: Cascade)\n\n  @@index([inventarioId])\n  @@index([produtoId])\n  @@index([produtoInternoId])\n}\n\n//////////////////////////////////////////////////////\n// DADOS DERIVADOS / OPERACIONAIS\n//////////////////////////////////////////////////////\n\n/// Indicadores pré-calculados por produto-farmácia.\nmodel IndicadoresProdutoFarmacia {\n  id                    String               @id @default(cuid())\n  produtoId             String\n  farmaciaId            String\n  mediaVendasDiarias30d Decimal?             @db.Decimal(14, 4)\n  mediaVendasDiarias90d Decimal?             @db.Decimal(14, 4)\n  mediaVendasMensais3m  Decimal?             @db.Decimal(14, 4)\n  mediaVendasMensais12m Decimal?             @db.Decimal(14, 4)\n  diasStockRestante     Decimal?             @db.Decimal(14, 2)\n  diasSemVenda          Int?\n  ultimoPrecoCompra     Decimal?             @db.Decimal(12, 4)\n  ultimoFornecedorId    String?\n  classificacaoABC      ClassificacaoABC     @default(NAO_CLASSIFICADO)\n  classificacaoRotacao  ClassificacaoRotacao @default(NORMAL)\n  valorStockParado      Decimal?             @db.Decimal(14, 2)\n  dataCalculo           DateTime             @updatedAt\n\n  produto          Produto     @relation(fields: [produtoId], references: [id], onDelete: Cascade)\n  farmacia         Farmacia    @relation(fields: [farmaciaId], references: [id], onDelete: Cascade)\n  ultimoFornecedor Fornecedor? @relation(\"IndicadorUltimoFornecedor\", fields: [ultimoFornecedorId], references: [id])\n\n  @@unique([produtoId, farmaciaId])\n  @@index([farmaciaId])\n  @@index([classificacaoRotacao])\n  @@index([classificacaoABC])\n  @@index([diasSemVenda])\n}\n\n/// Lista de encomenda guardada pelo utilizador.\nmodel ListaEncomenda {\n  id              String               @id @default(cuid())\n  farmaciaId      String\n  nome            String\n  estado          EstadoListaEncomenda @default(RASCUNHO)\n  /// Sub-estado do fluxo de exportação para SPharm. Aplica-se apenas\n  /// quando `estado = FINALIZADA`; em RASCUNHO o valor existe mas não\n  /// é consumido pelo agent (o outbox só cria rows para listas\n  /// finalizadas via createEncomendaWithOutbox). Default PENDENTE é\n  /// seguro porque sem OrderOutbox associado nada é exportado.\n  estadoExport    OrderExportState     @default(PENDENTE)\n  criadoPorId     String\n  dataCriacao     DateTime             @default(now())\n  dataAtualizacao DateTime             @updatedAt\n\n  farmacia  Farmacia         @relation(fields: [farmaciaId], references: [id], onDelete: Cascade)\n  criadoPor Utilizador       @relation(fields: [criadoPorId], references: [id])\n  linhas    LinhaEncomenda[]\n  outbox    OrderOutbox?\n\n  @@index([farmaciaId])\n  @@index([criadoPorId])\n  @@index([estado])\n  @@index([estadoExport])\n}\n\n/// De onde veio uma linha de encomenda.\n///\n/// PROPOSTA  — gerada pelo calculo automatico a partir de vendas.\n/// MANUAL    — o utilizador escolheu o artigo e escreveu a quantidade.\n/// SUGESTAO  — veio de uma sugestao aceite noutro ecra (excessos,\n///             transferencias) via prefill.\n///\n/// Serve para que um recalculo da proposta NAO destrua o que foi\n/// decidido a mao: so' as linhas PROPOSTA sao substituidas. Ver\n/// `lib/encomendas/origem-linha.ts`, onde a regra vive e e' testada.\nenum OrigemLinhaEncomenda {\n  PROPOSTA\n  MANUAL\n  SUGESTAO\n}\n\n/// Linhas da lista de encomenda.\nmodel LinhaEncomenda {\n  id                   String               @id @default(cuid())\n  listaEncomendaId     String\n  produtoId            String\n  quantidadeSugerida   Decimal?             @db.Decimal(14, 3)\n  quantidadeAjustada   Decimal?             @db.Decimal(14, 3)\n  fornecedorSugeridoId String?\n  notas                String?\n  /// Proveniencia da linha. Default PROPOSTA: e' o que todas as linhas\n  /// existentes sao — foram criadas pelo calculo automatico, que era o\n  /// unico caminho ate' agora. Nenhuma linha historica muda de\n  /// significado com esta coluna.\n  origem               OrigemLinhaEncomenda @default(PROPOSTA)\n\n  listaEncomenda     ListaEncomenda @relation(fields: [listaEncomendaId], references: [id], onDelete: Cascade)\n  produto            Produto        @relation(fields: [produtoId], references: [id], onDelete: Cascade)\n  fornecedorSugerido Fornecedor?    @relation(\"LinhaEncomendaFornecedorSugerido\", fields: [fornecedorSugeridoId], references: [id])\n\n  @@unique([listaEncomendaId, produtoId])\n  @@index([produtoId])\n  @@index([fornecedorSugeridoId])\n}\n\n/// Fila de revisão manual do catálogo.\nmodel FilaRevisao {\n  id            String            @id @default(cuid())\n  produtoId     String\n  tipoRevisao   TipoRevisao\n  prioridade    PrioridadeRevisao @default(MEDIA)\n  dadosOrigem   Json?\n  estado        EstadoFilaRevisao @default(PENDENTE)\n  dataCriacao   DateTime          @default(now())\n  dataResolucao DateTime?\n\n  produto Produto @relation(fields: [produtoId], references: [id], onDelete: Cascade)\n\n  @@index([estado, prioridade])\n  @@index([produtoId])\n  @@index([tipoRevisao])\n}\n\n/// Fila técnica para enriquecimento automático.\nmodel EnriquecimentoFila {\n  id               String               @id @default(cuid())\n  produtoId        String\n  prioridade       PrioridadeRevisao    @default(MEDIA)\n  ultimaTentativa  DateTime?\n  numeroTentativas Int                  @default(0)\n  estado           EnriquecimentoEstado @default(PENDENTE)\n  ultimaFonte      String?\n  mensagemErro     String?\n  dataCriacao      DateTime             @default(now())\n  dataAtualizacao  DateTime             @updatedAt\n\n  produto Produto @relation(fields: [produtoId], references: [id], onDelete: Cascade)\n\n  @@unique([produtoId])\n  @@index([estado, prioridade])\n}\n\n//////////////////////////////////////////////////////\n// INGESTÃO\n//////////////////////////////////////////////////////\n\n/// Registo de cada lote recebido/processado.\nmodel LoteIngestao {\n  id                String             @id @default(cuid())\n  farmaciaId        String\n  tipo              TipoLoteIngestao\n  dataReferencia    DateTime\n  dataProcessamento DateTime?\n  estado            EstadoLoteIngestao @default(RECEBIDO)\n  totalRegistos     Int?\n  totalAceites      Int?\n  totalRejeitados   Int?\n  mensagemErro      String?\n  nomeFicheiro      String?\n  blobUrl           String?\n  hashConteudo      String?\n  dataCriacao       DateTime           @default(now())\n  dataAtualizacao   DateTime           @updatedAt\n\n  farmacia Farmacia @relation(fields: [farmaciaId], references: [id], onDelete: Cascade)\n\n  vendas           Venda[]\n  vendasMensais    VendaMensal[]\n  compras          Compra[]\n  devolucoes       Devolucao[]\n  historicoStocks  HistoricoStock[]\n  produtosInternos ProdutoInterno[]\n  ajustesStock     AjusteStock[]\n  inventarios      Inventario[]\n\n  @@index([farmaciaId, tipo, dataReferencia])\n  @@index([estado])\n}\n\n//////////////////////////////////////////////////////\n// INGESTÃO RAW — STAGING DO BOOTSTRAP DO AGENT\n//\n// Tabelas que recebem dados do agent bootstrap-upload em formato\n// **raw**, sem agregação. Distintas das tabelas operacionais (Venda,\n// VendaMensal) porque preservam todos os campos do ERP por linha,\n// incluindo TipoDocumento e raw JSON, para caracterização e replay.\n//\n// O passo seguinte (futuro) — uma vez consolidada a semântica de\n// [Tipo Documento] e [Valor_EUR] — vai aggregar estas linhas em\n// VendaMensal via job server-side. Por agora, esta tabela é apenas\n// staging.\n//////////////////////////////////////////////////////\n\n/// Linhas de venda raw vindas do ERP Softreis via agent bootstrap.\n///\n/// Idempotência forte: `@@unique(farmaciaId, sourceNamespace,\n/// externalSaleLineId)`. Reupload da mesma linha actualiza-a.\n///\n/// A chave INCLUI a origem desde 2026-08-18. Antes era\n/// `(farmaciaId, externalSaleLineId)`, o que assumia que o ERP tinha uma\n/// só tabela de linhas de venda. Tem mais: uma factura da série VSG\n/// (venda suspensa, que fiscalmente é uma venda como outra qualquer)\n/// vive em `[Atendimento Susp Detalhe]`, com a sua própria sequência de\n/// IDs. Duas sequências independentes não podem partilhar uma chave —\n/// ingerir a segunda sobrescreveria linhas da primeira assim que os\n/// contadores se cruzassem.\nmodel IngestVendaLinhaRaw {\n  id         String @id @default(cuid())\n  farmaciaId String\n\n  /// A tabela ERP de onde a linha veio. Faz parte da identidade.\n  /// Valores: \"ATENDIMENTO_DETALHE\" | \"ATENDIMENTO_SUSP_DETALHE\".\n  /// String e não enum: acrescentar uma fonte não deve exigir migração\n  /// de tipo em todos os tenants.\n  sourceNamespace String @default(\"ATENDIMENTO_DETALHE\")\n\n  /// Softreis: Atendimento.[Atendimento ID]. Header da venda.\n  externalSaleId     Int\n  /// PK da linha DENTRO da sua tabela (`[Detalhe ID]` ou\n  /// `[Atendimento Susp Detalhe ID]`). Só é comparável com linhas do\n  /// mesmo `sourceNamespace`.\n  externalSaleLineId Int\n\n  /// Série documental do cabeçalho (\"G\", \"VSG\"). Null quando o ERP não\n  /// a expõe. Informativa — a classificação vem de `tipoDocumento`.\n  serie     String?\n  /// \"VSG/54688\" — série e número compostos, para reconciliar com o ERP.\n  documento String?\n  /// Sequência da linha dentro do atendimento. Permite ordenar e\n  /// distinguir linhas duplicadas legítimas no mesmo Atendimento ID.\n  sequencia Int?\n\n  dataVenda          DateTime?\n  /// Softreis: Atendimento.[Tipo Documento]. Raw int.\n  tipoDocumento      Int?\n  /// Classificação JS-side ao recepcionar a linha. Strings simples\n  /// para não criar dependência cross-tenant em Prisma enums.\n  /// Valores conhecidos: \"VENDA\", \"DEVOLUCAO_ANULACAO\", \"UNKNOWN\".\n  tipoDocumentoClass String\n\n  /// O que a linha É: \"NORMAL\" | \"CREDITO\" | \"TRANSFERENCIA\".\n  ///\n  /// Dimensão ORTOGONAL a `tipoDocumentoClass`, que diz se soma ou\n  /// subtrai. Uma devolução de venda a crédito é DEVOLUCAO_ANULACAO +\n  /// CREDITO; numa coluna só, nenhuma das duas perguntas teria resposta.\n  ///\n  /// O relatório oficial do SPharm tem dois interruptores — incluir\n  /// vendas a crédito, incluir guias de transferência. Um total já\n  /// somado não se desliga, por isso a natureza sobrevive até ao UI.\n  naturezaVenda String @default(\"NORMAL\")\n\n  /// Softreis: CodigoID. Sempre presente.\n  externalProductId Int\n  /// Resolvido server-side em best-effort via Produto.externalProductId.\n  /// Null quando o produto não está em Stocks (data quality issue —\n  /// agent reporta no dry-run e aqui fica registo permanente).\n  produtoId         String?\n  /// Linha técnica/serviço sem produto operacional (Softreis:\n  /// Stocks.[Processa_Stocks] = 0). Inclui taxas (entrega ao\n  /// domicílio, serviço), administração de injectáveis,\n  /// rastreios Checksaude, etc. Marcado server-side quando o\n  /// agent envia `processaStocks=false` E o lookup ao Produto\n  /// falha. Excluído da agregação `VendaMensal`.\n  isNonStockService Boolean @default(false)\n\n  quantidade       Decimal? @db.Decimal(14, 3)\n  pvpUnitario      Decimal? @db.Decimal(12, 4)\n  valorLinha       Decimal? @db.Decimal(14, 2)\n  ivaValor         Decimal? @db.Decimal(14, 2)\n  descontoValor    Decimal? @db.Decimal(14, 2)\n  comparticipacao1 Decimal? @db.Decimal(14, 2)\n  comparticipacao2 Decimal? @db.Decimal(14, 2)\n  entidadeId       Int?\n\n  /// Payload bruto recebido (forensic). Permite reprocessamento sem\n  /// re-query ao ERP se a interpretação mudar.\n  rawJson Json\n\n  importedAt DateTime @default(now())\n\n  farmacia Farmacia @relation(fields: [farmaciaId], references: [id], onDelete: Cascade)\n  produto  Produto? @relation(fields: [produtoId], references: [id], onDelete: SetNull)\n\n  @@unique([farmaciaId, sourceNamespace, externalSaleLineId])\n  @@index([farmaciaId, dataVenda])\n  @@index([externalSaleId])\n  @@index([sourceNamespace])\n  @@index([tipoDocumento])\n  @@index([produtoId])\n  @@index([isNonStockService])\n}\n\n//////////////////////////////////////////////////////\n// STAGING — COMPRAS + DEVOLUÇÕES A FORNECEDOR (Fase 1b.1)\n//////////////////////////////////////////////////////\n//\n// Tabelas de staging WRITE-ONLY nesta fase. Zero consumidores\n// downstream: dashboard, vendas, encomendas, export-orders e\n// `Compra`/`Devolucao` finais não tocam aqui. Fase 1c+ adicionará o\n// aggregator que escreve em `Compra`/`Devolucao`.\n//\n// Mapping validado (rev24 inspection.md):\n//   Compras   = dbo.Recepcao (header) + dbo.[Recepcao Detalhe] (linhas)\n//               · PK linha = [Detalhe  Recp ID] (DOIS espaços, quirk Softreis)\n//               · Filtro válido: RecepcaoSituacaoID = 'N'\n//               · Valor_EUR é UNITÁRIO; total linha = Quantidade × Valor_EUR\n//   Devoluções = dbo.Devolucao + dbo.[Devolucao Detalhe]\n//               · Sempre AO fornecedor (FK declarada a Fornecedores)\n//               · Filtro válido: DevolucaoSituacaoID <> 'A'\n//               · Valor em Devolucao Detalhe é TOTAL DA LINHA (Qt × PVF_EUR)\n//\n// Idempotência: `@@unique([farmaciaId, externalLineId])` em ambas.\n// Re-run do mesmo intervalo UPSERTa — devoluções P→R transition é\n// capturada via update de `devolucaoSituacaoId` + `quantidadeRecebida`.\n\n/// Linhas de compra (recepção de mercadoria) raw vindas do SPharm ERP\n/// local. 1 row por linha de dbo.[Recepcao Detalhe]. Header denormalizado\n/// em cada linha para reconciliação `SUM(qt × valorEurUnit) ≈ headerTotalIncidenciaEur`\n/// sem JOIN. Esta tabela é APENAS staging — Fase 1b não tem agregação.\nmodel StagingCompraRawLine {\n  id         BigInt @id @default(autoincrement())\n  farmaciaId String\n\n  // ── Identidade ERP ────────────────────────────────────────────\n  /// dbo.Recepcao.[Recepcao ID]. Header.\n  externalReceptionId Int\n  /// dbo.[Recepcao Detalhe].[Detalhe  Recp ID] (dois espaços no nome\n  /// do campo no SPharm — quirk Softreis preservado server-side).\n  /// PK natural da linha; base da idempotência.\n  externalLineId      Int\n  sequencia           Int?\n\n  // ── Header (denormalizado para reconciliação sem JOIN) ────────\n  /// dbo.Recepcao.[NRecepcao]. Numerador interno sequencial.\n  externalNRecepcao        Int\n  /// dbo.Recepcao.[Fornecedor ID]. Resolução para Fornecedor canónico\n  /// faz-se a jusante via FornecedorErpRef — não materializada aqui.\n  externalFornecedorId     Int\n  /// dbo.Recepcao.[FornecedorTipoDocumentoID] (Tipo Documento).\n  /// 99% Factura (2); resto: G/Remessa, G/Transporte, NC, NULL.\n  externalTipoDocumentoId  Int?\n  /// dbo.Recepcao.[Fornecedor_NDoc]. Nº documento externo do fornecedor.\n  externalFornecedorNDoc   String?\n  /// dbo.Recepcao.[Data Recepcao] — canónica para data de operação.\n  dataRecepcao             DateTime\n  /// dbo.Recepcao.[Fornecedor_Data] — data da factura externa.\n  fornecedorData           DateTime?\n  /// dbo.Recepcao.[ArmazemID]. v1 assume single-warehouse por farmácia.\n  armazemId                Int\n  /// dbo.Recepcao.[RecepcaoSituacaoID]. Filtrado a 'N' no SQL; capturado\n  /// para auditoria + safety net.\n  recepcaoSituacaoId       String\n  headerTotalBrutoEur      Decimal   @db.Decimal(12, 2)\n  headerTotalIvaEur        Decimal   @db.Decimal(12, 2)\n  headerTotalIncidenciaEur Decimal   @db.Decimal(12, 2)\n\n  // ── Linha (raw, NÃO agregada) ────────────────────────────────\n  /// dbo.[Recepcao Detalhe].CodigoID → resolvido para Produto via\n  /// ProdutoFarmacia.externalProductId a jusante (fora desta fase).\n  externalCodigoId     Int\n  quantidade           Int\n  bonus                Int\n  iva                  Decimal   @db.Decimal(4, 2)\n  desconto             Decimal?  @db.Decimal(7, 2)\n  /// dbo.[Recepcao Detalhe].[Preco Venda Publico_EUR].\n  precoVendaPublicoEur Decimal   @db.Decimal(8, 2)\n  /// dbo.[Recepcao Detalhe].[Valor_EUR]. **UNITÁRIO** (PVF c/ desconto,\n  /// sem IVA). Total linha = quantidade × valorEurUnit. Validado rev24\n  /// pelas amostras 4.1. Naming explícito para impedir confusão.\n  valorEurUnit         Decimal   @db.Decimal(10, 2)\n  validade             DateTime?\n\n  ingestedAt    DateTime @default(now())\n  /// Batch ULID emitido pelo agent. Permite cleanup direccionado:\n  /// `DELETE WHERE ingestBatchId = ?` para reverter passagem específica.\n  ingestBatchId String\n\n  farmacia Farmacia @relation(fields: [farmaciaId], references: [id], onDelete: Cascade)\n\n  @@unique([farmaciaId, externalLineId])\n  @@index([farmaciaId, dataRecepcao])\n  @@index([farmaciaId, externalCodigoId, dataRecepcao])\n  @@index([farmaciaId, externalFornecedorId, dataRecepcao])\n  @@index([farmaciaId, ingestBatchId])\n}\n\n/// Linhas de devolução a fornecedor raw vindas do SPharm ERP local.\n/// 1 row por linha de dbo.[Devolucao Detalhe]. dbo.Devolucao é SEMPRE\n/// AO fornecedor — FK declarada a dbo.Fornecedores garante. Devoluções\n/// de cliente (raras) fluem por Atendimento Detalhe com TipoDocumento=104,\n/// não entram aqui.\n///\n/// Estados capturados: P (Pendente), E (Parcialmente Resolvida),\n/// R (Resolvida), X (Pend.Emissão). Anuladas (A) excluídas no SQL.\n/// Transição P→R muda `quantidadeRecebida` (0 → >0) sem alterar PK;\n/// re-sync via UPSERT captura.\nmodel StagingDevolucaoFornecedorRawLine {\n  id         BigInt @id @default(autoincrement())\n  farmaciaId String\n\n  // ── Identidade ERP ────────────────────────────────────────────\n  /// dbo.Devolucao.[Devolucao ID]. Header.\n  externalDevolucaoId Int\n  /// dbo.[Devolucao Detalhe].[Devolucao Detalhe ID]. PK natural da linha.\n  externalLineId      Int\n  sequencia           Int?\n\n  // ── Header (denormalizado) ────────────────────────────────────\n  externalNDevolucao   Int\n  externalFornecedorId Int\n  dataDevolucao        DateTime\n  /// 'P' | 'E' | 'R' | 'X'. NUNCA 'A' (filtrado no SQL).\n  devolucaoSituacaoId  String\n  armazemId            Int\n  /// dbo.Devolucao.[Observacoes]. Texto livre operador.\n  observacoes          String?\n\n  // ── SAFT compliance (auditoria fiscal PT) ────────────────────\n  serieFacturacao String?\n  atcud           String?\n  ncertAt         Int?\n  systemEntryDate DateTime?\n\n  headerTotalDocumento     Decimal @db.Decimal(9, 2)\n  headerTotalIvaEur        Decimal @db.Decimal(12, 2)\n  headerTotalIncidenciaEur Decimal @db.Decimal(12, 2)\n\n  // ── Linha ─────────────────────────────────────────────────────\n  externalCodigoId     Int\n  /// Qt enviada ao fornecedor (decisão operacional, momento da emissão).\n  quantidadeEnviada    Int\n  /// Qt aceite pelo fornecedor após resolução. = 0 enquanto estado='P'.\n  quantidadeRecebida   Int\n  bonus                Int?\n  /// dbo.[Devolucao Detalhe].[Motivo] → dbo.Motivos (FK declarada).\n  motivoId             Int?\n  iva                  Decimal   @db.Decimal(4, 2)\n  /// dbo.[Devolucao Detalhe].[PVP_EUR].\n  precoVendaPublicoEur Decimal?  @db.Decimal(8, 2)\n  /// dbo.[Devolucao Detalhe].[PVF_EUR]. UNITÁRIO (PVF c/ desconto).\n  pvfEurUnit           Decimal?  @db.Decimal(8, 2)\n  /// dbo.[Devolucao Detalhe].[Valor]. **TOTAL DA LINHA**\n  /// (Qt Enviada × PVF_EUR). Validado rev24 pelas amostras 4.2.\n  /// Atenção: semântica diferente de StagingCompraRawLine.valorEurUnit.\n  valorEurTotal        Decimal?  @db.Decimal(9, 2)\n  validade             DateTime?\n  lote                 String?\n  /// dbo.[Devolucao Detalhe].[Recepcao_Origem]. Texto livre não-estruturado\n  /// (ex: \"Factura 26385870\"). Captura mas não permite JOIN à recepção\n  /// original. Auditoria de custo-de-origem ficaria deferida para outra fase.\n  recepcaoOrigemText   String?\n  recepcaoOrigemData   DateTime?\n\n  ingestedAt    DateTime @default(now())\n  ingestBatchId String\n\n  farmacia Farmacia @relation(fields: [farmaciaId], references: [id], onDelete: Cascade)\n\n  @@unique([farmaciaId, externalLineId])\n  @@index([farmaciaId, dataDevolucao])\n  @@index([farmaciaId, externalCodigoId, dataDevolucao])\n  @@index([farmaciaId, externalFornecedorId, dataDevolucao])\n  @@index([farmaciaId, devolucaoSituacaoId])\n  @@index([farmaciaId, ingestBatchId])\n}\n\n/// Registo de cada execução do pipeline autónomo daily-sync → aggregate\n/// → reports. Auditoria + base do health check + página /admin/pipeline.\n///\n/// Modelo single-shot: o agent (ou o endpoint server-side) POSTa **uma**\n/// row com `status='RUNNING'` quando arranca, e faz UPDATE para\n/// `OK`/`ERROR`/`ABORTED` no fim. Não é uma máquina de estados com\n/// transições intermédias — apenas marca início e fim com payload\n/// estruturado em `details`.\n///\n/// Kinds suportados (string livre, sem enum Prisma para flexibilidade):\n///   · \"daily-pipeline\"    — orquestrador completo do agent on-prem\n///   · \"daily-sync\"        — sub-passo (raro: o orquestrador agrega)\n///   · \"aggregate-month\"   — agregação VendaMensal server-side\n///\n/// `details` é JSON com counts/timings/IDs operacionais. Estrutura\n/// canónica documentada em `lib/pipeline/types.ts`.\n///\n/// Garantias de leitura:\n///   · `[farmaciaId, kind, startedAt]` indexado → última execução por\n///     tipo num único query\n///   · `[status, startedAt]` indexado → listagem de falhas recentes\n///   · Sem retenção automática — opera com 1 row por dia × kind, ou\n///     seja ~3 rows/dia × tenant. 12 meses = ~1k rows. Append-only.\nmodel PipelineRun {\n  id             String    @id @default(cuid())\n  farmaciaId     String\n  kind           String\n  startedAt      DateTime  @default(now())\n  finishedAt     DateTime?\n  /// \"RUNNING\" | \"OK\" | \"ERROR\" | \"ABORTED\"\n  status         String    @default(\"RUNNING\")\n  /// Período coberto. YYYY-MM-DD para daily-*, YYYY-MM para aggregate.\n  dateRef        String?\n  durationMs     Int?\n  errorMessage   String?\n  /// JSON estruturado — ver lib/pipeline/types.ts para shape.\n  details        Json      @default(\"{}\")\n  /// \"agent\" | \"operator\" | \"admin\" | \"scheduler\"\n  triggeredBy    String    @default(\"agent\")\n  /// Chave determinística enviada pelo agent (ex:\n  /// `daily-pipeline:<farmaciaId>:<dateRef>:<startedAt-iso>`). Quando\n  /// presente, /api/admin/pipeline/record faz upsert por esta chave em\n  /// vez de criar nova row — defesa contra retries do agent que\n  /// duplicariam o audit log. Opcional para back-compat com agents\n  /// antigos que não enviam.\n  idempotencyKey String?\n  createdAt      DateTime  @default(now())\n  updatedAt      DateTime  @updatedAt\n\n  farmacia Farmacia @relation(fields: [farmaciaId], references: [id], onDelete: Cascade)\n\n  @@unique([idempotencyKey])\n  @@index([farmaciaId, kind, startedAt])\n  @@index([status, startedAt])\n}\n\n/// Lookup de classificação semântica para `Atendimento.[Tipo Documento]`.\n/// PK natural = valor raw do ERP (Int). Aplicado no endpoint\n/// `/api/ingest/v1/bootstrap/sales-lines` no momento do upsert; também\n/// usado pelo script `scripts/reclassify-ingest-vendas.ts` para\n/// reclassificar `IngestVendaLinhaRaw` já carregada.\n///\n/// Classes válidas (string, sem enum Prisma para flexibilidade de\n/// reclassificação retroactiva sem migration):\n///   · VENDA               — venda comercial; entra em VendaMensal\n///   · DEVOLUCAO_ANULACAO  — sinal negativo na agregação\n///   · UNKNOWN             — caracterização pendente; staging conserva\n///                           a linha mas agregação ignora\n///   · IGNORE_TECHNICAL    — linha técnica (consulta, anulação interna);\n///                           staging conserva mas agregação ignora\n///\n/// Editável via SQL directo OU script `scripts/classify-tipodoc.ts`.\n/// O endpoint lê esta tabela em cada batch — alteração é imediata\n/// para uploads futuros. Para staging existente, correr o reclassify\n/// script.\nmodel TipoDocumentoClassificacao {\n  /// Valor raw do ERP — Atendimento.[Tipo Documento]\n  tipoDocumento Int      @id\n  /// Classe canónica SPharm.MT — uma das 4 strings acima\n  classe        String\n  /// Label legível (ex: \"Venda OTC sem receita\", \"Anulação interna\")\n  descricao     String?\n  /// Notas livres para contexto operacional\n  notas         String?\n  /// Quem classificou (email do operador, \"system\" para seeds, ou\n  /// \"agent-fallback\" se mantido por compat)\n  classifiedBy  String?\n  classifiedAt  DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  @@index([classe])\n}\n\n//////////////////////////////////////////////////////\n// OUTBOX DOWNSTREAM (SPharmMT → SPharm)\n//\n// Fluxo outbound para exportar listas de encomenda criadas em\n// SPharmMT para a base de dados SQL Server da farmácia (SPharm).\n// Aplicação do padrão transactional outbox: a linha OrderOutbox é\n// criada na MESMA transacção do ListaEncomenda, garantindo que\n// nenhuma ordem fica órfã.\n//\n// O agent Windows (scheduled task --pull-downstream, 5 em 5 min):\n//   1. GET /api/outbox/v1/orders/pending → recebe rows já leased\n//   2. Escreve cada encomenda no SQL Server SPharm (transacção local)\n//   3. POST /orders/{id}/ack com o spharmDocumentId retornado\n//   4. Em falha → POST /orders/{id}/nack com retryable=true|false\n//\n// Idempotência: cada outbox row tem um idempotencyKey determinístico\n// derivado de tenantSlug + listaEncomendaId. A estratégia exacta de\n// reconhecimento desse key em SPharm fica provisional até recebermos\n// o schema real do SPharm — ver doc §4.2 do plano bidireccional.\n//////////////////////////////////////////////////////\n\n/// Outbox de exportação de encomendas. 1:1 com ListaEncomenda.\n/// Criado na mesma transacção via lib/ingest/orders.ts:createEncomendaWithOutbox.\nmodel OrderOutbox {\n  id               String @id @default(cuid())\n  listaEncomendaId String @unique\n  /// Denormalizado para permitir index (farmaciaId, state) sem join\n  /// na query hot-path do agent.\n  farmaciaId       String\n\n  /// Snapshot congelado do payload que o agent vai escrever em SPharm.\n  /// JSON serializado. IMUTÁVEL — edições à lista após criação do\n  /// outbox requerem cancelar+recriar (ver lib/ingest/orders.ts).\n  payloadJson String\n\n  /// Chave determinística: \"{tenantSlug}:{listaEncomendaId}\". Usada\n  /// pelo agent como stamp para idempotência em SPharm. A ferramenta\n  /// de stamping em SPharm será decidida quando chegar o schema real.\n  idempotencyKey String @unique\n\n  /// Hash sha256 do payloadJson. Se o mesmo idempotencyKey alguma vez\n  /// aparecer com hash diferente, o agent deve abortar e marcar\n  /// FALHADO — defesa contra mutação acidental do payload congelado.\n  payloadHash String\n\n  state OrderExportState @default(PENDENTE)\n\n  /// Contador de tentativas (incluindo a corrente). Reset a 0 no /retry.\n  attemptCount  Int       @default(0)\n  /// Próxima janela elegível para o agent claim. now() inicial.\n  /// Schedule de retry: 1m · 5m · 30m · 2h · 8h · 24h · então FALHADO.\n  nextAttemptAt DateTime  @default(now())\n  lastError     String?\n  lastAttemptAt DateTime?\n\n  // ── Lease ────────────────────────────────────────────────────────\n  /// Identificador da instância do agent que reclamou a row.\n  /// Null quando não há lease activa.\n  leasedBy    String?\n  /// TTL da lease. 5 min por defeito — próximo run reclama após isto.\n  leasedUntil DateTime?\n\n  // ── Confirmação ──────────────────────────────────────────────────\n  /// Número de documento atribuído por SPharm depois do INSERT.\n  /// Preenchido no endpoint /ack.\n  spharmDocumentId String?\n  exportedAt       DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  listaEncomenda ListaEncomenda     @relation(fields: [listaEncomendaId], references: [id], onDelete: Cascade)\n  audits         OrderExportAudit[]\n\n  // Hot path: o agent pede pending rows ordenadas por nextAttemptAt.\n  @@index([state, nextAttemptAt])\n  // Hot path: admin UI lista por farmácia + estado.\n  @@index([farmaciaId, state])\n  // Liveness check admin: \"qual foi a última tentativa?\"\n  @@index([lastAttemptAt])\n}\n\n/// Histórico imutável de tentativas de exportação. NUNCA apagar linhas.\n/// Cada /ack, /nack, /retry e /cancel grava uma row aqui para\n/// rastreabilidade operacional. O OrderOutbox guarda apenas o estado\n/// corrente; a timeline completa vive aqui.\nmodel OrderExportAudit {\n  id             String   @id @default(cuid())\n  outboxId       String\n  attempt        Int\n  at             DateTime @default(now())\n  /// \"ATTEMPT\" | \"SUCCESS\" | \"FAILURE\" | \"RETRY_SCHEDULED\" |\n  /// \"GAVE_UP\" | \"MANUAL_RETRY\" | \"MANUAL_CANCEL\" | \"LEASE_CLAIMED\" |\n  /// \"LEASE_RELEASED\" | \"LEASE_EXPIRED\"\n  status         String\n  message        String?\n  httpStatus     Int?\n  spharmSqlError String?\n  /// ID do utilizador que executou a acção manual, se aplicável.\n  /// Null para acções do agent.\n  actorId        String?\n\n  outbox OrderOutbox @relation(fields: [outboxId], references: [id], onDelete: Cascade)\n\n  @@index([outboxId, at])\n  @@index([status, at])\n}\n\n//////////////////////////////////////////////////////\n// MOVIMENTO ARTIGO (canonical, StocksMov-derived)\n//////////////////////////////////////////////////////\n\n/// Movimento canónico de stock por artigo, derivado 1:1 de\n/// `dbo.StocksMov` no SPharm ERP (audit rev32). Substitui semanticamente\n/// a união ad-hoc de Venda/Compra/Devolucao no extrato; as tabelas\n/// legadas permanecem para dashboard/analytics até deprecação futura.\n///\n/// Granularidade: 1 row por StocksMovID. PK natural compósita\n/// `(farmaciaId, externalMovId)` garante idempotência do upload e do\n/// backfill — re-correr a mesma janela produz UPDATE, não duplica.\n///\n/// Cada linha tem exactamente 1 das 6 colunas FK populadas (origem do\n/// movimento). O classificador `lib/movimento-classifier.ts` mapeia\n/// essa FK + enrichment de Cab.Motivo/TipoDoc → `tipo`.\n///\n/// `existenciaApos` é o running balance pós-movimento (StocksMov.Existencia\n/// no ERP). Permite reconstruir \"stock antes/depois\" sem inventar dados.\nmodel MovimentoArtigo {\n  id                String  @id @default(cuid())\n  farmaciaId        String\n  /// dbo.StocksMov.StocksMovID. PK natural ERP — base da idempotência.\n  externalMovId     Int\n  /// CodigoID do ERP serializado para string (preserva valores acima\n  /// de 2^53). Resolução para `produtoId` faz-se a jusante via\n  /// ProdutoFarmacia.externalProductId; null quando produto não\n  /// existe em catálogo (orfão).\n  externalProductId String\n  produtoId         String?\n\n  /// dbo.StocksMov.DataMov. Timestamp do movimento (não a data SAFT).\n  dataMovimento DateTime\n  tipo          TipoMovimentoArtigo\n\n  /// dbo.StocksMov.Qtd (assinado: negativo = saída). Preserva o sinal\n  /// para reconciliação fiel; UI converte a |value| + direcao.\n  quantidade      Int\n  /// @deprecated rev36: substituído por `quantidadeBonusEnt`/`Sai` +\n  /// `existenciaBonusApos`. Mantido para compat com leitores legacy;\n  /// remover em cleanup futuro após todos os tenants estarem em rev36.\n  quantidadeBonus Int     @default(0)\n  /// dbo.StocksMov.Existencia. Running balance APÓS este movimento.\n  existenciaApos  Int\n  custoUnitario   Decimal @db.Decimal(12, 4)\n  /// dbo.StocksMov.OldPMC.\n  pmcAnterior     Decimal @db.Decimal(12, 4)\n  /// dbo.StocksMov.NovoPMC.\n  pmcNovo         Decimal @db.Decimal(12, 4)\n  armazemId       Int\n\n  // ── FK origem (exactamente 1 populada em 99,9 % das linhas) ────\n  /// dbo.StocksMov.[Detalhe ID] — venda / devolução cliente.\n  externalDetalheId          Int?\n  /// dbo.StocksMov.[Atendimento Susp Detalhe ID] — reserva suspensa.\n  externalSuspDetalheId      Int?\n  /// dbo.StocksMov.[Atendimento Credito Detalhe ID] — venda crédito.\n  externalCreditoDetalheId   Int?\n  /// dbo.StocksMov.[Detalhe  Recp ID] (dois espaços, quirk Softreis) —\n  /// compra / recepção.\n  externalRecpDetalheId      Int?\n  /// dbo.StocksMov.[Devolucao Detalhe ID] — devolução a fornecedor.\n  externalDevolucaoDetalheId Int?\n  /// dbo.StocksMov.MovStocksDetID — movimento interno.\n  externalMovStocksDetId     Int?\n\n  // ── Enrichment via tblMovStocksCab (MOV_INTERNO) ───────────────\n  movStocksCabId          Int?\n  /// dbo.tblMovStocksCab.[Tipo Documento ID]. Fallback do classificador\n  /// quando `MovStocksCabMotivoID IS NULL` (84 % dos Mov_Interno em\n  /// alguns tenants — ex: Segurado audit rev32).\n  movStocksCabTipoDocId   Int?\n  /// dbo.tblMovStocksCab.MovStocksCabMotivoID. ID LOCAL ao tenant\n  /// (Segurado 1..30 ≠ Silveirense 0..65 mesma semântica). Preservado\n  /// para auditoria; classificação canónica vive no campo `tipo`.\n  movStocksCabMotivoId    Int?\n  /// Texto do motivo (dbo.tblMovStocksCab_Motivo.Motivo) já resolvido\n  /// no agent — o classificador trabalha sobre este texto normalizado.\n  movStocksCabMotivoTexto String?\n  /// 'N' = Normal, 'A' = Anulado. Anulados ficam visíveis no extrato\n  /// (UI pinta cinza) com `tipo` regular; permite auditoria total.\n  movStocksCabSituacao    String?\n  movStocksCabUserId      Int?\n  movStocksCabPosto       Int?\n  movStocksCabNDocExterno String?\n\n  // ── Enrichment via Atendimento (VENDA / DEVOLUCAO_CLIENTE) ────\n  /// dbo.Atendimento Detalhe → Atendimento.[Atendimento ID].\n  externalSaleId  Int?\n  /// dbo.Atendimento.[Tipo Documento ID]: 7=VENDA, 104/27=DEV_CLIENTE,\n  /// 2=VENDA (raro). Usado pelo classificador para sub-tipar VENDA vs\n  /// DEVOLUCAO_CLIENTE entre os Stocksmov que partilham FK [Detalhe ID].\n  tipoDocumentoId Int?\n\n  // ── ERP parity rev36 ───────────────────────────────────────────\n  // Composto no agent a partir do FK pattern: para vendas vem de\n  // Atendimento+Atendimento_TipoDocumento, para compras de Recepcao_Cab,\n  // para devForn de Devolucao_Cab, para mov-interno de tblMovStocksCab.\n  // Permite mostrar \"Factura G/783019\", \"Recepção 60566\", \"Nota Crédito\n  // VSG/25113\", \"G/Transferência VCG_1/2169\" tal como no relatório ERP.\n  documentoTipo     String? @db.VarChar(40)\n  documentoNumero   String? @db.VarChar(40)\n  /// Referência cruzada quando aplicável: talão original de uma NC,\n  /// factura externa do fornecedor, nº de doc na farmácia de origem\n  /// numa transferência. NULL para mov-interno puro.\n  referenciaExterna String? @db.VarChar(80)\n\n  /// Nome legível da contraparte (cliente / fornecedor / farmácia\n  /// origem ou destino). Resolvido no agent via JOIN ao schema SoftReis.\n  /// NULL para mov-interno puro (inventário/quebra/ajuste).\n  contraparteNome String?          @db.VarChar(160)\n  contraparteTipo ContraparteTipo?\n\n  /// dbo.Armazens.Designacao. Nome amigável; `armazemId` continua a ser\n  /// a referência canónica.\n  armazemNome    String? @db.VarChar(60)\n  /// dbo.Operadores.Nome via StocksMov.OperadorID. Rastreabilidade do\n  /// operador que executou o movimento (não impresso pelo ERP no\n  /// relatório, está apenas em ficha técnica).\n  utilizadorNome String? @db.VarChar(80)\n\n  // ── Bónus split (rev36) ────────────────────────────────────────\n  // O ERP imprime Bónus+ / Bónus- / Ex.Bon separadamente. `quantidadeBonus`\n  // (combinado, pré-rev36) mantém-se para compatibilidade temporária mas\n  // deprecará após cleanup. Origem: dbo.StocksMov.BonusEnt/BonusSai e\n  // dbo.StocksMov.ExistenciaBonus.\n  quantidadeBonusEnt  Int @default(0)\n  quantidadeBonusSai  Int @default(0)\n  existenciaBonusApos Int @default(0)\n\n  // ── Preço / valor (rev36) ──────────────────────────────────────\n  /// dbo.StocksMov.PrecoVenda (PVP da linha de venda) ou PUC da compra.\n  precoUnitario Decimal? @db.Decimal(12, 4)\n  /// dbo.StocksMov.ValorVenda ou ValorCompra. Total monetário da linha\n  /// tal como contabilizado no ERP (preserva o que o ERP imprimiu, sem\n  /// recalcular qty × preço — diferenças de IVA, descontos, bonus).\n  valorLinha    Decimal? @db.Decimal(12, 2)\n\n  ingestRunId String?\n  ingestedAt  DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  farmacia Farmacia @relation(fields: [farmaciaId], references: [id], onDelete: Cascade)\n  produto  Produto? @relation(fields: [produtoId], references: [id], onDelete: SetNull)\n\n  /// Idempotência: re-upload da mesma janela UPDATE-a em vez de duplicar.\n  @@unique([farmaciaId, externalMovId])\n  @@index([farmaciaId, externalProductId, dataMovimento])\n  @@index([farmaciaId, dataMovimento, tipo])\n  @@index([farmaciaId, tipo, dataMovimento])\n  @@index([produtoId, dataMovimento])\n  @@index([farmaciaId, movStocksCabId])\n  @@index([ingestRunId])\n}\n\n/// Staging mirror raw de `dbo.StocksMov + JOINs`. 1 row por POST do\n/// agent; preservado para auditoria post-mortem e re-classificação se\n/// o classificador mudar. Sem FKs ao catálogo — é um snapshot bruto.\n/// Cleanup é direccionado por `ingestRunId`.\nmodel IngestStocksMovRaw {\n  id            BigInt   @id @default(autoincrement())\n  farmaciaId    String\n  externalMovId Int\n  /// Payload completo da linha StocksMov + JOINs (Cab/Det/Motivo/Atendimento).\n  /// O classificador trabalha sobre este JSON; útil para replay.\n  payload       Json\n  ingestRunId   String\n  ingestedAt    DateTime @default(now())\n\n  farmacia Farmacia @relation(fields: [farmaciaId], references: [id], onDelete: Cascade)\n\n  @@unique([farmaciaId, externalMovId, ingestRunId])\n  @@index([farmaciaId, ingestRunId])\n  @@index([ingestedAt])\n}\n\n/// Cache do knowledge-enrichment (lib/catalog/knowledge-enrichment.ts).\n///\n/// Porquê existir: o resultado para \"Ozempic 0.25 Mg Sol. Injetável\" é o\n/// mesmo hoje e daqui a um mês. Sem cache, o job diário voltava a pagar o\n/// catálogo residual inteiro todos os dias para reconfirmar o que já\n/// sabia. Com cache, a primeira corrida paga o backlog e as seguintes só\n/// pagam o que entrou de novo.\n///\n/// A chave é (versão do prompt, modelo, cnp, designação normalizada) —\n/// tudo o que muda a resposta. Mudar o prompt ou o modelo não invalida\n/// nada em massa: passa a haver linhas novas ao lado das antigas, o que\n/// deixa comparar duas versões sobre o mesmo catálogo.\n///\n/// Guarda-se o resultado MESMO quando não foi persistido (confiança baixa\n/// ou DESCONHECIDO). É isso que impede o job de voltar a perguntar todos\n/// os dias por produtos que já se sabe que o modelo não reconhece — o\n/// caso mais caro se ficasse de fora.\nmodel KnowledgeEnrichmentCache {\n  /// `${versao}|${modelo}|${cnp}|${designacao normalizada}`\n  chave String @id\n\n  cnp        Int\n  designacao String\n  versao     String\n  modelo     String\n\n  productType  String?\n  categoria    String?\n  subcategoria String?\n  forma        String?\n  utilizacoes  String[] @default([])\n  confidence   Float\n  evidenceType String\n  rationale    String?\n\n  /// ke-2.0 — campos clínicos inferidos pelo modelo.\n  ///\n  /// Guardados aqui mesmo quando não são persistidos em `Produto`: é o\n  /// que torna a corrida idempotente. Sem isto, uma segunda passagem\n  /// voltaria a pagar a chamada para um produto cujo ATC já se sabe que\n  /// veio abaixo do limiar.\n  dci               String?\n  codigoATC         String?\n  dosagem           String?\n  embalagem         String?\n  /// Confiança nos campos clínicos, distinta de `confidence`.\n  confidenceClinica Float?\n\n  /// O que o modelo REALMENTE respondeu, antes de `isValidNivel2`.\n  ///\n  /// `categoria`/`subcategoria` acima só sobrevivem em par válido: um par\n  /// que a taxonomia não tem era anulado em silêncio e a cache guardava\n  /// `null`, indistinguível de \"o modelo não respondeu\". Perdia-se\n  /// exactamente o sinal que diz se o problema é do modelo ou da nossa\n  /// taxonomia — e como a resposta já estava paga, perdia-se pago.\n  ///\n  /// Guardados SEMPRE, válidos ou não. Nunca são escritos em `Produto`.\n  categoriaBruta    String?\n  subcategoriaBruta String?\n\n  /// Quando esta linha foi reavaliada por uma política posterior, e por\n  /// que versão. É o que torna o reprocessamento idempotente e retomável:\n  /// uma corrida interrompida a meio sabe onde ficou.\n  reavaliadoEm     DateTime?\n  reavaliadoVersao String?\n\n  /// Foi escrito no Produto, ou ficou só registado? Distingue \"o modelo\n  /// não soube\" de \"o modelo soube e nós recusámos\" na hora de explicar\n  /// uma cobertura que não subiu.\n  persistido Boolean @default(false)\n  /// Porque não foi persistido, quando não foi.\n  motivo     String?\n\n  /// De onde veio este resultado: CLAUDE (decisão do modelo sobre ESTE\n  /// produto) ou PROPAGADO (conclusão sobre um irmão da mesma família\n  /// estrita, aplicada aqui). Sem isto, uma auditoria futura não\n  /// conseguiria separar as duas coisas.\n  origem         String?\n  /// cnp do representante, quando origem = PROPAGADO.\n  propagadoDeCnp Int?\n\n  criadoEm DateTime @default(now())\n\n  @@index([cnp])\n  @@index([versao, evidenceType])\n  @@index([persistido])\n  @@index([reavaliadoVersao])\n}\n",
